"use client";

import type { PropsWithChildren } from "react";
import { useRouter } from "next/navigation";
import {
  ClerkProvider as ReactClerkProvider,
} from "@clerk/react";

const publishableKey = process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY;

if (process.env.NODE_ENV === "production") {
  const redactedKey = publishableKey
    ? `${publishableKey.slice(0, 6)}… (len=${publishableKey.length})`
    : "<undefined>";
  console.log(
    `[Clerk] NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY=${redactedKey}. NODE_ENV=${process.env.NODE_ENV}`,
  );
}
let missingKeyWarningLogged = false;

export function ClientClerkProvider({ children }: PropsWithChildren): React.JSX.Element {
  const router = useRouter();

  if (!publishableKey) {
    if (process.env.NODE_ENV !== "production" && !missingKeyWarningLogged) {
      missingKeyWarningLogged = true;
      console.warn("Clerk publishable key is not configured. Authentication is disabled.");
    }
    return <>{children}</>;
  }

  return (
    <ReactClerkProvider
      publishableKey={publishableKey}
      routerPush={(to) => router.push(to)}
      routerReplace={(to) => router.replace(to)}
    >
      {children}
    </ReactClerkProvider>
  );
}

