'use client';

import * as React from 'react';
import { motion, LayoutGroup } from 'motion/react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { AvatarGroup, AvatarGroupTooltip } from '@/components/animate-ui/components/avatar-group';
import { cn } from '@/lib/utils';
import { Dock, DockIcon } from "@/components/ui/dock";
import { TooltipProvider } from "@/components/animate-ui/components/tooltip";

// Types and Constants
// =================================================================

export type CommunityItem = {
  id: string;
  label: string;
  iconUrl?: string | null;
};

export interface CommunityPresenceSelectorProps {
  items: CommunityItem[];
  className?: string;
  size?: 'sm' | 'md' | 'lg';
  value?: string[] | null;
  onChange?: (selected: string[] | null) => void;
  tooltipSide?: 'top' | 'bottom' | 'left' | 'right';
  tooltipOffset?: number;
  overlap?: 'tight' | 'normal';
  hoverLift?: string | number;
}

const AVATAR_MOTION_TRANSITION = { type: 'spring' as const, stiffness: 200, damping: 25 };
const GROUP_CONTAINER_TRANSITION = { type: 'spring' as const, stiffness: 150, damping: 20 };
const ANIMATION_DURATION = 500; // ms

// Helper Components
// =================================================================

const MemoizedTooltipContent = React.memo(({ label }: { label: string }) => {
  return <p>{label}</p>;
});
MemoizedTooltipContent.displayName = 'MemoizedTooltipContent';

function fallbackText(label: string) {
  if (!label) return '?';
  const t = label.trim();
  if (/\s/.test(t)) {
    const parts = t.split(/\s+/).filter(Boolean);
    const head = parts[0] || t;
    return head.slice(0, 2);
  }
  return t.slice(0, 2);
}

// View Components (Memoized for Performance)
// =================================================================

const CollapsedView = React.memo(({ selected, items, dims }: { selected: CommunityItem[], items: CommunityItem[], dims: { s: string, b: string } }) => {
  const firstSelected = selected[0] ?? items[0];
  if (!firstSelected) return null;

  return (
    <div className={cn("relative grid place-items-center", dims.s)}>
      {items.map((c, i) => (
        <motion.div
          key={c.id}
          layoutId={`avatar-${c.id}`}
          className="col-start-1 row-start-1"
          style={{ opacity: c.id === firstSelected.id ? 1 : 0, zIndex: items.length - i }}
        >
          <Avatar className={cn(dims.s, dims.b, "border-neutral-300 dark:border-neutral-700")}>
            {c.iconUrl ? <AvatarImage src={c.iconUrl} /> : null}
            <AvatarFallback>{fallbackText(c.label)}</AvatarFallback>
          </Avatar>
        </motion.div>
      ))}
      {selected.length > 1 && (
        <div className={cn("absolute bottom-0 right-0 translate-x-1/2 translate-y-1/4 bg-blue-500 text-white text-xs rounded-full h-5 min-w-[1.25rem] px-1.5 flex items-center justify-center border-2 border-white z-50")}>
          +{selected.length - 1}
        </div>
      )}
    </div>
  );
});
CollapsedView.displayName = 'CollapsedView';

const DockView = React.memo(({ items, unselected, toggle, dims }: { items: CommunityItem[], unselected: CommunityItem[], toggle: (id: string) => void, dims: { s: string, b: string } }) => (
  <div className="flex items-center justify-center h-full">
    <Dock direction="middle" iconSize={32} iconMagnification={48} className="border-none bg-transparent p-0 shadow-none backdrop-blur-none">
      {items.reverse().map((c: CommunityItem) => (
        <DockIcon key={c.id}>
          <motion.div layoutId={`avatar-${c.id}`} className="cursor-pointer" onClick={() => toggle(c.id)}>
            <Avatar className={cn(dims.s, dims.b, "border-neutral-300 dark:border-neutral-700", unselected.some((u: CommunityItem) => u.id === c.id) && "grayscale")}>
              {c.iconUrl ? <AvatarImage src={c.iconUrl} /> : null}
              <AvatarFallback>{fallbackText(c.label)}</AvatarFallback>
            </Avatar>
          </motion.div>
        </DockIcon>
      ))}
    </Dock>
  </div>
));
DockView.displayName = 'DockView';

const ExpandedView = React.memo(({ selected, unselected, toggle, dims, space, hoverLift, tooltipSide, tooltipOffset, togglingGroup, className }: { 
  selected: CommunityItem[];
  unselected: CommunityItem[];
  toggle: (id: string) => void;
  dims: { h: string; s: string; b: string };
  space: string;
  hoverLift?: string | number;
  tooltipSide?: 'top' | 'bottom' | 'left' | 'right';
  tooltipOffset?: number;
  togglingGroup: 'selected' | 'unselected' | null;
  className?: string;
}) => (
  <div className={cn('flex items-center justify-center gap-4', className)}>
    {selected.length > 0 && (
      <motion.div layout className={cn('bg-neutral-200 dark:bg-neutral-700/70 p-0.5 rounded-full', togglingGroup === 'selected' ? 'z-5' : 'z-10')} transition={GROUP_CONTAINER_TRANSITION}>
        <AvatarGroup key={selected.map((u: CommunityItem) => u.id).join('_') + '-selected'} className={cn(dims.h, space)} translate={hoverLift} tooltipProps={{ side: tooltipSide, sideOffset: tooltipOffset }}>
          {selected.map((c: CommunityItem) => (
            <motion.div key={c.id} layoutId={`avatar-${c.id}`} className="cursor-pointer" onClick={() => toggle(c.id)} animate={{ filter: 'grayscale(0)', scale: 1 }} transition={AVATAR_MOTION_TRANSITION} initial={false}>
              <Avatar className={cn(dims.s, dims.b, 'border-neutral-300 dark:border-neutral-700')}>
                {c.iconUrl ? <AvatarImage src={c.iconUrl} /> : null}
                <AvatarFallback>{fallbackText(c.label)}</AvatarFallback>
                <AvatarGroupTooltip><MemoizedTooltipContent label={c.label} /></AvatarGroupTooltip>
              </Avatar>
            </motion.div>
          ))}
        </AvatarGroup>
      </motion.div>
    )}
    {unselected.length > 0 && (
      <motion.div layout className={cn('bg-neutral-200 dark:bg-neutral-700/70 p-0.5 rounded-full', togglingGroup === 'unselected' ? 'z-5' : 'z-10')} transition={GROUP_CONTAINER_TRANSITION}>
        <AvatarGroup key={unselected.map((u: CommunityItem) => u.id).join('_') + '-unselected'} className={cn(dims.h, space)} translate={hoverLift} tooltipProps={{ side: tooltipSide, sideOffset: tooltipOffset }}>
          {unselected.map((c: CommunityItem) => (
            <motion.div key={c.id} layoutId={`avatar-${c.id}`} className="cursor-pointer" onClick={() => toggle(c.id)} animate={{ filter: 'grayscale(1)', scale: 1 }} transition={AVATAR_MOTION_TRANSITION} initial={false}>
              <Avatar className={cn(dims.s, dims.b, 'border-neutral-300 dark:border-neutral-700')}>
                {c.iconUrl ? <AvatarImage src={c.iconUrl} /> : null}
                <AvatarFallback>{fallbackText(c.label)}</AvatarFallback>
                <AvatarGroupTooltip><MemoizedTooltipContent label={c.label} /></AvatarGroupTooltip>
              </Avatar>
            </motion.div>
          ))}
        </AvatarGroup>
      </motion.div>
    )}
  </div>
));
ExpandedView.displayName = 'ExpandedView';

// Main Component
// =================================================================

export default function CommunityPresenceSelector({ items, className, size = 'md', value, onChange, tooltipSide = 'top', tooltipOffset = 14, overlap = 'normal', hoverLift }: CommunityPresenceSelectorProps) {
  const controlled = value !== undefined;
  const [internalSelectedIds, setInternalSelectedIds] = React.useState<string[]>(() => items.map(i => i.id));
  const [togglingGroup, setTogglingGroup] = React.useState<'selected' | 'unselected' | null>(null);
  const [isHovered, setIsHovered] = React.useState(false);
  const [isAnimating, setIsAnimating] = React.useState(false);
  const animationTimer = React.useRef<NodeJS.Timeout | undefined>(undefined);

  // Animate on hover change
  React.useEffect(() => {
    setIsAnimating(true);
    animationTimer.current = setTimeout(() => setIsAnimating(false), ANIMATION_DURATION);
    return () => {
      if (animationTimer.current) clearTimeout(animationTimer.current);
    };
  }, [isHovered]);

  // Sync state with props
  const effectiveSelectedIds: string[] = React.useMemo(() => {
    if (controlled) {
      if (value === null) return items.map(i => i.id);
      const allowed = new Set(items.map(i => i.id));
      return (value || []).filter(id => allowed.has(id));
    }
    return internalSelectedIds;
  }, [controlled, value, items, internalSelectedIds]);

  const itemIds = React.useMemo(() => items.map(i => i.id).join(','), [items]);
  React.useEffect(() => {
    if (!controlled) {
      setInternalSelectedIds(items.map(i => i.id));
      onChange?.(null);
    }
  }, [itemIds, controlled, onChange, items]);

  const selected = React.useMemo(() => items.filter(i => effectiveSelectedIds.includes(i.id)), [items, effectiveSelectedIds]);
  const unselected = React.useMemo(() => items.filter(i => !effectiveSelectedIds.includes(i.id)), [items, effectiveSelectedIds]);

  // Memoize display-related values
  const dims = React.useMemo(() => size === 'lg' ? { h: 'h-14', s: 'size-14', b: 'border-4' } : size === 'sm' ? { h: 'h-8', s: 'size-8', b: 'border-2' } : { h: 'h-12', s: 'size-12', b: 'border-3' }, [size]);
  const space = React.useMemo(() => overlap === 'tight' ? '-space-x-2' : '-space-x-3', [overlap]);

  // Memoize callback
  const toggle = React.useCallback((id: string) => {
    const prev = effectiveSelectedIds;
    const has = prev.includes(id);
    const next = has ? prev.filter((x: string) => x !== id) : [...prev, id];
    if (next.length === 0) return;
    setTogglingGroup(has ? 'selected' : 'unselected');
    const allIds = items.map(i => i.id);
    const allSelected = next.length === allIds.length && allIds.every(x => next.includes(x));
    onChange?.(allSelected ? null : [...next]);
    if (!controlled) setInternalSelectedIds(next);
    setTimeout(() => setTogglingGroup(null), 500);
  }, [effectiveSelectedIds, items, onChange, controlled]);

  const renderContent = () => {
    const showDock = isAnimating;
    const showExpanded = isHovered && !isAnimating;
    const showCollapsed = !isHovered && !isAnimating;

    if (showDock) {
      return <DockView items={[...selected, ...unselected]} unselected={unselected} toggle={toggle} dims={dims} />;
    }
    if (showExpanded) {
      return <ExpandedView selected={selected} unselected={unselected} toggle={toggle} dims={dims} space={space} hoverLift={hoverLift} tooltipSide={tooltipSide} tooltipOffset={tooltipOffset} togglingGroup={togglingGroup} className={className} />;
    }
    if (showCollapsed) {
      return <CollapsedView selected={selected} items={[...selected, ...unselected]} dims={dims} />;
    }
    return null;
  };

  return (
    <TooltipProvider>
      <div
        className={cn('flex items-center justify-center min-h-[64px]', className)}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <LayoutGroup>{renderContent()}</LayoutGroup>
      </div>
    </TooltipProvider>
  );
}

"use client";

import * as React from "react";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Badge } from "@/components/ui/badge";
import { LayoutGrid, List, Clock as ClockIcon, CircleDot, Circle } from "lucide-react";
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover";
import type { ViewMode, ReadFilter } from "@/lib/feed-prefs";
import type { Range } from "@/lib/types";
import { useIsMobile } from "@/components/ui/use-mobile";
import { CountingNumber } from "@/components/animate-ui/text/counting-number";

/** 기본 라벨(원하는 값으로 오버라이드 가능) */
const DEFAULT_RANGE_LABELS: Record<Range, string> = {
    "3h": "3시간",
    "6h": "6시간",
    "24h": "24시간",
    "1w": "1주일",
};

export interface FeedControlsProps {
    type?: "category" | "keyword";
    id?: string;
    range: Range;
    viewMode: ViewMode;
    readFilter: ReadFilter;
    setRange: (r: Range) => void;
    setViewMode: (v: ViewMode) => void;
    setReadFilter: (f: ReadFilter) => void;
    rangeOrder?: Range[];
    rangeLabels?: Partial<Record<Range, string>>;
    metricsKey?: string;
}

export function FeedControls({
    range,
    viewMode,
    readFilter,
    setRange,
    setViewMode,
    setReadFilter,
    rangeOrder,
    rangeLabels,
    metricsKey,
}: FeedControlsProps) {
    const order = (rangeOrder && rangeOrder.length ? rangeOrder : ["3h", "6h", "24h", "1w"]) as Range[];
    const labels = { ...DEFAULT_RANGE_LABELS, ...(rangeLabels || {}) } as Record<Range, string>;

    const [isPending] = React.useTransition();

    const [metrics, setMetrics] = React.useState<{ total: number; read: number; unread: number } | null>(null);
    const lastRxRef = React.useRef<{ total: number; read: number; unread: number } | null>(null);
    const rxRafRef = React.useRef<number | null>(null);
    React.useEffect(() => {
        const onMetrics = (e: Event) => {
            try {
                const ce = e as CustomEvent<{ key: string; total: number; read: number; unread: number }>;
                const d = ce.detail;
                if (!d) return;
                if (metricsKey && d.key !== metricsKey) {
                    if (process.env.NODE_ENV !== 'production') {
                        // eslint-disable-next-line no-console
                        console.log('[FeedControls] metrics event', {
                            incomingKey: d.key, expectKey: metricsKey,
                            total: d.total, read: d.read, unread: d.unread
                        });
                    }
                    return;
                }

                if (lastRxRef.current && lastRxRef.current.total === d.total && lastRxRef.current.read === d.read && lastRxRef.current.unread === d.unread) {
                    if (process.env.NODE_ENV !== 'production') {
                        // eslint-disable-next-line no-console
                        console.log('[FeedControls] metrics unchanged, skip');
                    }
                    return;
                }
                lastRxRef.current = { total: d.total, read: d.read, unread: d.unread };
                if (rxRafRef.current != null) cancelAnimationFrame(rxRafRef.current);
                rxRafRef.current = requestAnimationFrame(() => {
                    rxRafRef.current = null;
                    setMetrics(lastRxRef.current);
                });
            } catch { /* ignore */ }
        };
        window.addEventListener('feed:metrics', onMetrics);
        return () => {
            window.removeEventListener('feed:metrics', onMetrics);
            if (rxRafRef.current != null) cancelAnimationFrame(rxRafRef.current);
        };
    }, [metricsKey]);

    const isMobile = useIsMobile();

    return (
        <div className={`flex items-center gap-3 transition-opacity ${isPending ? 'opacity-75' : ''}`}>
            <fieldset disabled={isPending} className="contents">
                {isMobile ? (
                    <>
                        <Popover>
                            <PopoverTrigger asChild>
                                <button
                                    type="button"
                                    aria-label={`시간 범위: ${labels[range]}`}
                                    aria-haspopup="menu"
                                    className="rounded-md border px-2 py-1 text-sm inline-flex items-center gap-2"
                                    title="시간 범위 선택"
                                >
                                    <ClockIcon className="h-4 w-4" />
                                    <span aria-hidden>{labels[range]}</span>
                                </button>
                            </PopoverTrigger>
                            <PopoverContent align="start" className="w-44 p-1" sideOffset={6}>
                                <div className="px-2 py-1 text-[13px] text-gray-500" aria-hidden>
                                    최근 글 범위
                                </div>
                                <div role="menu" aria-label="시간 범위" className="pb-1">
                                    {order.map((r) => (
                                        <button
                                            key={r}
                                            role="menuitemradio"
                                            aria-checked={range === r}
                                            className={`w-full text-left px-2 py-1.5 rounded-md text-sm ${range === r ? 'bg-gray-100 dark:bg-neutral-800 font-medium' : 'hover:bg-gray-50 dark:hover:bg-neutral-900'}`}
                                            onClick={() => setRange(r)}
                                        >
                                            {labels[r]}
                                        </button>
                                    ))}
                                </div>
                                <div className="mt-1 pt-1 border-t">
                                    <button
                                        type="button"
                                        className="w-full text-left px-2 py-1.5 rounded-md text-sm inline-flex items-center justify-between hover:bg-gray-50 dark:hover:bg-neutral-900"
                                        onClick={() => setReadFilter('read')}
                                        aria-label="읽은 글만 보기"
                                        title="읽은 글만 보기"
                                    >
                                        <span>읽은 글만 보기</span>
                                        {metrics && (
                                            <Badge variant="secondary" className="px-1.5 py-0 h-5 text-xs bg-gray-100 text-gray-800 border-0" aria-label={`읽은 글 ${metrics.read}개`}>
                                                <CountingNumber number={metrics.read} />
                                            </Badge>
                                        )}
                                    </button>
                                </div>
                            </PopoverContent>
                        </Popover>

                        <button
                            type="button"
                            aria-label={readFilter === 'unread' ? '안 읽은 글만: 켜짐' : '안 읽은 글만: 꺼짐'}
                            aria-pressed={readFilter === 'unread'}
                            className="rounded-md border px-2 py-1 text-sm inline-flex items-center gap-2"
                            onClick={() => setReadFilter(readFilter === 'unread' ? 'all' : 'unread')}
                            title="안 읽은 글만 보기 토글"
                        >
                            {readFilter === 'unread' ? <CircleDot className="h-4 w-4" /> : <Circle className="h-4 w-4" />}
                            <span className="sr-only">안 읽은 글만</span>
                            {metrics && (
                                <Badge
                                    variant="secondary"
                                    className="px-1.5 py-0 h-5 text-xs bg-blue-100 text-blue-800 border-0"
                                    aria-label={
                                        readFilter === 'read'
                                            ? `전체 ${metrics.total}개`
                                            : `${readFilter === 'unread' ? '안 읽은 글' : '전체'} ${readFilter === 'unread' ? metrics.unread : metrics.total}개`
                                    }
                                >
                                    <CountingNumber number={readFilter === 'read'
                                        ? metrics.total
                                        : (readFilter === 'unread' ? metrics.unread : metrics.total)} />
                                </Badge>
                            )}
                            <span className="sr-only">{readFilter === 'read' ? '현재 보기: 읽은 글만' : '현재 보기: 전체/안 읽은 글 필터'}</span>
                        </button>

                        <button
                            type="button"
                            aria-label="보기 모드"
                            className="rounded-md border px-2 py-1"
                            onClick={() => setViewMode(viewMode === 'grid' ? 'list' : 'grid')}
                            title="그리드/리스트 전환"
                        >
                            {viewMode === 'grid' ? <List className="h-4 w-4" /> : <LayoutGrid className="h-4 w-4" />}
                        </button>
                    </>
                ) : (
                    <>
                        <Popover>
                            <PopoverTrigger asChild>
                                <button
                                    type="button"
                                    aria-label={`시간 범위: ${labels[range]}`}
                                    aria-haspopup="menu"
                                    className="rounded-md border px-2 py-1 text-sm inline-flex items-center gap-2"
                                    title="시간 범위 선택"
                                >
                                    <ClockIcon className="h-4 w-4" />
                                    <span aria-hidden>{labels[range]}</span>
                                </button>
                            </PopoverTrigger>
                            <PopoverContent align="start" className="w-44 p-1" sideOffset={6}>
                                <div className="px-2 py-1 text-[13px] text-gray-500" aria-hidden>
                                    최근 글 범위
                                </div>
                                <div role="menu" aria-label="시간 범위" className="pb-1">
                                    {order.map((r) => (
                                        <button
                                            key={r}
                                            role="menuitemradio"
                                            aria-checked={range === r}
                                            className={`w-full text-left px-2 py-1.5 rounded-md text-sm ${range === r ? 'bg-gray-100 dark:bg-neutral-800 font-medium' : 'hover:bg-gray-50 dark:hover:bg-neutral-900'}`}
                                            onClick={() => setRange(r)}
                                        >
                                            {labels[r]}
                                        </button>
                                    ))}
                                </div>
                                <div className="mt-1 pt-1 border-t">
                                    <button
                                        type="button"
                                        className="w-full text-left px-2 py-1.5 rounded-md text-sm inline-flex items-center justify-between hover:bg-gray-50 dark:hover:bg-neutral-900"
                                        onClick={() => setReadFilter('read')}
                                        aria-label="읽은 글만 보기"
                                        title="읽은 글만 보기"
                                    >
                                        <span>읽은 글만 보기</span>
                                        {metrics && (
                                            <Badge variant="secondary" className="px-1.5 py-0 h-5 text-xs bg-gray-100 text-gray-800 border-0" aria-label={`읽은 글 ${metrics.read}개`}>
                                                <CountingNumber number={metrics.read} />
                                            </Badge>
                                        )}
                                    </button>
                                </div>
                            </PopoverContent>
                        </Popover>

                        <button
                            type="button"
                            aria-label={readFilter === 'unread' ? '안 읽은 글만: 켜짐' : '안 읽은 글만: 꺼짐'}
                            aria-pressed={readFilter === 'unread'}
                            className="rounded-md border px-2 py-1 inline-flex items-center gap-2"
                            onClick={() => setReadFilter(readFilter === 'unread' ? 'all' : 'unread')}
                            title="안 읽은 글만 보기 토글"
                        >
                            {readFilter === 'unread' ? <CircleDot className="h-4 w-4" /> : <Circle className="h-4 w-4" />}
                            {metrics && (
                                <Badge
                                    variant="secondary"
                                    className="px-1.5 py-0 h-5 text-xs bg-blue-100 text-blue-800 border-0"
                                    aria-label={
                                        readFilter === 'read'
                                            ? `전체 ${metrics.total}개`
                                            : `${readFilter === 'unread' ? '안 읽은 글' : '전체'} ${readFilter === 'unread' ? metrics.unread : metrics.total}개`
                                    }
                                >
                                    <CountingNumber number={readFilter === 'read'
                                        ? metrics.total
                                        : (readFilter === 'unread' ? metrics.unread : metrics.total)} />
                                </Badge>
                            )}
                            <span className="sr-only">{readFilter === 'read' ? '현재 보기: 읽은 글만' : '현재 보기: 전체/안 읽은 글 필터'}</span>
                        </button>

                        <ToggleGroup
                            type="single"
                            value={viewMode}
                            onValueChange={(value) => { if (value) setViewMode(value as ViewMode); }}
                            aria-label="보기 모드"
                        >
                            <ToggleGroupItem value="grid" aria-label="그리드 보기">
                                <LayoutGrid className="h-4 w-4" />
                            </ToggleGroupItem>
                            <ToggleGroupItem value="list" aria-label="리스트 보기">
                                <List className="h-4 w-4" />
                            </ToggleGroupItem>
                        </ToggleGroup>
                    </>
                )}
            </fieldset>
            <span className="sr-only" aria-live="polite">
                {metrics ? `전체 ${metrics.total}개, 안 읽은 글 ${metrics.unread}개, 읽은 글 ${metrics.read}개` : ''}
            </span>
        </div>
    );
}

