"use client";

import { useEffect, useRef, useState, useCallback, useMemo, useLayoutEffect } from "react";
import { useSearchParams } from "next/navigation";
import { PostCard } from "@/components/post-card";
import type { Post } from "@/lib/types";
import { onCommunity, onCommunities } from "@/lib/communityFilter";
import { getManifest as cacheGetManifest, readPage as cacheReadPage, writePage as cacheWritePage } from "@/lib/idb-cache";
import type { ClientPost } from "@/lib/idb-cache";
import {
  defaultRangeExtractor,
  measureElement as defaultMeasureElement,
  useWindowVirtualizer,
} from "@tanstack/react-virtual";
import type { Range, Virtualizer } from "@tanstack/react-virtual";
import { readAndClearRestore } from "@/lib/restore-session";
import { usePostCache } from "@/context/post-cache-context";
import { subscribeToPreviewActivations } from "@/lib/preview-activation-store";
import { useFeedScrollMargin } from '@/hooks/use-feed-scroll-margin';
import { correctFeedViewportAnchor, findFeedAnchorElement, virtualRowOffset } from '@/lib/virtual-feed-geometry';
import { findSurvivingFeedAnchor, reconcileFeedSeed } from '@/lib/feed-refresh';

// --- Constants ---
const MISSING_LIMIT = 2;
const RETRY_BACKOFFS = [200, 400, 800];
const FAILED_PAGE_RETRY_WINDOW = 10000; // 10s
const MAX_PAGES_PER_CALL = 2;
const READ_POSTS_KEY = 'readPosts:v2';

const FALLBACK_VIEWPORT_HEIGHT = 900;
const FALLBACK_ROW_ESTIMATE = 200;
const HALF_VIEWPORT_BUFFER_RATIO = 0.3;
const MIN_BUFFER_ROWS = 2;
const MAX_BUFFER_ROWS = 64;
const LOAD_AHEAD_VIEWPORT_MULTIPLIER = 1.0;
const MANIFEST_TTL_MS = 5000;

export type VirtualBufferSizing = {
  overscanRows: number;
  loadAheadRows: number;
  estimatedRowHeight: number;
  viewportHeight: number;
};

export function deriveVirtualBufferSizing({
  estimatedRowHeight,
  viewportHeight,
  ratio = HALF_VIEWPORT_BUFFER_RATIO,
  minRows = MIN_BUFFER_ROWS,
  maxRows = MAX_BUFFER_ROWS,
  overscanOverride,
  loadAheadOverride,
}: {
  estimatedRowHeight: number;
  viewportHeight: number;
  ratio?: number;
  minRows?: number;
  maxRows?: number;
  overscanOverride?: number;
  loadAheadOverride?: number;
}): VirtualBufferSizing {
  const safeEstimate = Number.isFinite(estimatedRowHeight) && estimatedRowHeight > 0
    ? Math.round(estimatedRowHeight)
    : FALLBACK_ROW_ESTIMATE;
  const safeViewport = Number.isFinite(viewportHeight) && viewportHeight > 0
    ? Math.round(viewportHeight)
    : FALLBACK_VIEWPORT_HEIGHT;

  const estimatedViewportRows = Math.max(1, Math.round(safeViewport / safeEstimate));
  const derived = Math.ceil(((safeViewport * ratio) || 0) / safeEstimate);
  const clampedOverscan = overscanOverride != null
    ? Math.max(minRows, Math.min(maxRows, Math.round(overscanOverride)))
    : Math.max(minRows, Math.min(maxRows, derived || minRows));

  const loadAheadBase = loadAheadOverride != null
    ? Math.max(1, Math.round(loadAheadOverride))
    : Math.max(1, Math.round(estimatedViewportRows * LOAD_AHEAD_VIEWPORT_MULTIPLIER));
  const clampedLoadAhead = Math.max(clampedOverscan, Math.min(maxRows * 2, loadAheadBase));

  return {
    overscanRows: clampedOverscan,
    loadAheadRows: clampedLoadAhead,
    estimatedRowHeight: safeEstimate,
    viewportHeight: safeViewport,
  };
}

const MISSING_LOOKAHEAD = 4; // pages to probe ahead before declaring no more content (slightly more tolerant of sparse tails)
const FIRST_JSON_PAGE = 2; // page-1.json은 존재하지 않음. SSR(DB) 결과가 논리적 1페이지.

// --- Debug ---
const DEBUG_IPL = process.env.NODE_ENV !== 'production';
// Generate unique instance ID for debugging React Strict Mode
let instanceCounter = 0;
const dlog = (...args: unknown[]) => {
  if (DEBUG_IPL) {
    // Prefix with component tag and timestamp for easier tracing
    const ts = new Date().toISOString();
    // eslint-disable-next-line no-console
    console.log(`[InfinitePostList ${ts}]`, ...args);
  }
};

// --- Types ---
type LoadStatus = "ok-new" | "ok-dup" | "missing" | "error";
type LoadResult = { status: LoadStatus; newPosts: Post[] };
type ManifestSnapshot = { generatedAt: string; lastPage?: number; hasMore?: boolean; seedPolicy?: string; fetchedAt: number };

// Jump to an absolute measured offset before our cancellable DOM anchoring.
// Unlike scrollToIndex, scrollToOffset does not retarget the row when later
// measurements change. Core 3.17 still reconciles the absolute scroll command.
function scrollToFeedRow(virtualizer: ReturnType<typeof useWindowVirtualizer>, row: number) {
  virtualizer.getVirtualItems();
  const target = virtualizer.getOffsetForIndex(row, 'start');
  dlog('scroll:coarse', { row, count: virtualizer.options.count, offset: target?.[0], margin: virtualizer.options.scrollMargin });
  if (target) virtualizer.scrollToOffset(target[0], { align: 'start', behavior: 'auto' });
}

type FeedNavigationApi = {
  getIds: () => string[];
  hasMore: () => boolean;
  requestLoadMore: () => void;
};

declare global {
  interface Window {
    __FEED_NAV__?: Map<string, FeedNavigationApi>;
  }
}

// --- Restore Hook (extract) ---
function useRestoreFromDetail(params: {
  storageKeyPrefix: string | undefined;
  initialPage: number;
  cols: number;
  layoutReady: boolean;
  virtualizer: ReturnType<typeof useWindowVirtualizer>;
  loadMore: () => Promise<void>;
  hasMoreRef: React.MutableRefObject<boolean>;
  pageRef: React.MutableRefObject<number>;
  colsReadyRef: React.MutableRefObject<boolean>;
  visiblePostsRef: React.MutableRefObject<Post[]>;
  seenIdsRef: React.MutableRefObject<Set<string>>;
  postIdToPageNumRef: React.MutableRefObject<Map<string, number>>;
  rootRef: React.MutableRefObject<HTMLDivElement | null>;
  restoringRef: React.MutableRefObject<boolean>;
  ensureBelowBufferRows: (anchorId: string) => Promise<void>;
  userIntentRef: React.MutableRefObject<number>;
}) {
  const {
    storageKeyPrefix,
    initialPage,
    cols,
    layoutReady,
    virtualizer,
    loadMore,
    hasMoreRef,
    pageRef,
    colsReadyRef,
    visiblePostsRef,
    seenIdsRef,
    postIdToPageNumRef,
    rootRef,
    restoringRef,
    ensureBelowBufferRows,
    userIntentRef,
  } = params;
  const currentColsRef = useRef(cols);
  currentColsRef.current = cols;

  useEffect(() => {
    if (!layoutReady || !storageKeyPrefix || restoringRef.current) return;

    const restore = readAndClearRestore(storageKeyPrefix);
    if (!restore.should) return;

    restoringRef.current = true;
    let cancelled = false;
    const intent = userIntentRef.current;
    const isCancelled = () => cancelled || intent !== userIntentRef.current;
    const prevScrollBehavior = document.documentElement.style.scrollBehavior;
    let lateObserver: ResizeObserver | null = null;
    let lateFrame = 0;
    let lateTimeout: ReturnType<typeof setTimeout> | undefined;

    const run = async () => {
      document.documentElement.style.scrollBehavior = 'auto';

      const waitFrames = (n: number) => new Promise<void>((res) => {
        let i = 0; const step = () => { if (isCancelled() || ++i >= n) return res(); requestAnimationFrame(step); };
        requestAnimationFrame(step);
      });
      const checkActive = () => { if (isCancelled()) throw new Error('feed restore cancelled'); };

      const waitForAnchorStable = async (id: string) => {
        let el: HTMLElement | null = null;
        for (let i = 0; i < 60; i++) {
          checkActive();
          el = findFeedAnchorElement(rootRef.current, `post-${id}`);
          if (el) break;
          await waitFrames(1);
        }
        if (!el) return null;

        let stable = 0;
        let prev = -99999;
        for (let i = 0; i < 60; i++) {
          checkActive();
          const top = el.getBoundingClientRect().top;
          if (Math.abs(top - prev) <= 0.5) {
            stable++;
            if (stable >= 3) break;
          } else {
            stable = 0;
            prev = top;
          }
          await waitFrames(1);
        }
        return el;
      };

      const computeScrollOffset = () => {
        try {
          let offset = 0;
          // 1) Collect sticky/chrome heights
          const sel = [
            'header.sticky',
            '[data-sticky="top"]',
            '[data-slot="app-header"]',
            '.site-header',
            'nav.sticky',
          ];
          for (const s of sel) {
            const e = document.querySelector(s) as HTMLElement | null;
            if (e) offset = Math.max(offset, e.getBoundingClientRect().height || 0);
          }
          // 2) Section title or previous sibling under the header (if exists)
          const prevSibling = rootRef.current?.previousElementSibling as HTMLElement | null;
          if (prevSibling) offset += (prevSibling.getBoundingClientRect().height || 0) + 8;
          // 3) Prefer to keep the anchor a bit lower than the very top (≈12vh)
          const prefer = Math.round((typeof window !== 'undefined' ? window.innerHeight : 0) * 0.12);
          offset += prefer;
          // 4) Clamp to a sensible max: at most ~33vh and not above 360px
          const maxClamp = Math.max(96, Math.round(Math.min((typeof window !== 'undefined' ? window.innerHeight : 0) * 0.33, 360)));
          return Math.min(maxClamp, Math.max(0, Math.round(offset + 8)));
        } catch {
          // Fallback to a modest offset if anything goes wrong
          const safe = Math.round((typeof window !== 'undefined' ? window.innerHeight : 800) * 0.2);
          return Math.min(120, Math.max(64, safe));
        }
      };

      let anchorId: string | null = null;
      try {
        anchorId = restore.anchorPostId || null;
        const targetPage = Math.max(parseInt(String(restore.anchorPage ?? initialPage), 10) || initialPage, 1);

        // 컬럼 측정 + 가상행 생성까지 대기
        for (let i = 0; i < 60; i++) {
          checkActive();
          try {
            if (colsReadyRef.current && virtualizer.getVirtualItems().length > 0) break;
          } catch { /* ignore */ }
          await waitFrames(1);
        }

        // 타겟 페이지까지 로딩
        while (pageRef.current < targetPage && hasMoreRef.current) {
          checkActive();
          await loadMore();
          await waitFrames(2);
        }

        // 앵커 id가 목록에 들어올 때까지(필요시 더 로드)
        if (anchorId) {
          let guard = 0;
          while (!seenIdsRef.current.has(anchorId) && hasMoreRef.current && guard < 50) {
            checkActive();
            guard++;
            await loadMore();
            await waitFrames(2);
          }
        }

        // 1차: 해당 행으로 거칠게 이동
        checkActive();
        if (anchorId) {
          // Loading updates the raw IDs before React commits the filtered list.
          // Wait for that list and its virtual rows even when the last page ended.
          let rowIndex = -1;
          for (let i = 0; i < 60; i++) {
            checkActive();
            const idx = visiblePostsRef.current.findIndex((p) => p.id === anchorId);
            const candidateRow = Math.floor(idx / Math.max(1, currentColsRef.current));
            if (idx >= 0 && candidateRow < virtualizer.options.count) {
              rowIndex = candidateRow;
              break;
            }
            await waitFrames(1);
          }
          checkActive();
          if (rowIndex < 0) {
            dlog('restore:anchor-unavailable', { anchorId });
            return;
          }
          try { scrollToFeedRow(virtualizer, rowIndex); } catch { /* ignore */ }
          await waitFrames(2);

          // 2차: 요소가 DOM에 안정적으로 올라온 뒤 scroll-margin-top으로 정확히 맞추기
          const el2 = await waitForAnchorStable(anchorId);
          checkActive();
          if (el2) {
            const off = computeScrollOffset();
            el2.style.scrollMarginTop = `${off}px`;
            el2.scrollIntoView({ behavior: 'auto', block: 'start' });
            // post-correct on the next frame if we still ended up too high/low
            await waitFrames(1);
            checkActive();
            try {
              const top = el2.getBoundingClientRect().top;
              const delta = top - off; // negative => scroll up a bit; positive => scroll down a bit
              if (Math.abs(delta) > 0.5) {
                window.scrollBy({ top: delta, behavior: 'auto' });
              }
            } catch { /* ignore */ }
          }

          await ensureBelowBufferRows(anchorId);

          // Second-pass correction after tail priming & potential re-measure
          await waitFrames(2);
          checkActive();
          await waitFrames(1);
          checkActive();
          try {
            const el3 = findFeedAnchorElement(rootRef.current, `post-${anchorId}`);
            if (el3) {
              const off = computeScrollOffset();
              const rect = el3.getBoundingClientRect();
              const topDelta = rect.top - off; // negative => need to scroll up; positive => scroll down
              if (Math.abs(topDelta) > 0.5) {
                window.scrollBy({ top: topDelta, behavior: 'auto' });
              }
            }
          } catch { /* ignore */ }

          // Third-pass: watch for late reflow on the anchor for a short window
          try {
            const anchorEl = findFeedAnchorElement(rootRef.current, `post-${anchorId}`);
            if (anchorEl && 'ResizeObserver' in window) {
              const desiredTop = computeScrollOffset();
              const ro = new ResizeObserver(() => {
                if (isCancelled()) return;
                if (lateFrame) cancelAnimationFrame(lateFrame);
                lateFrame = requestAnimationFrame(() => {
                  if (isCancelled()) return;
                  try {
                    const rect = anchorEl.getBoundingClientRect();
                    const delta = rect.top - desiredTop;
                    if (Math.abs(delta) > 0.5) {
                      window.scrollBy({ top: delta, behavior: 'auto' });
                    }
                  } catch { /* ignore */ }
                });
              });
              lateObserver = ro;
              ro.observe(anchorEl);
              lateTimeout = setTimeout(() => {
                try { ro.disconnect(); } catch { }
                if (lateFrame) cancelAnimationFrame(lateFrame);
              }, 800);
            }
          } catch { /* ignore */ }


          // 복원 완료 후 URL의 ?page=를 앵커 카드의 JSON 페이지로 정규화
          checkActive();
          try {
            const setPageInUrl = (n: number) => {
              const u = new URL(window.location.href);
              if (n <= 1) u.searchParams.delete('page');
              else u.searchParams.set('page', String(n));
              const qs = u.searchParams.toString();
              window.history.replaceState(
                null,
                '',
                u.pathname + (qs ? `?${qs}` : '') + u.hash
              );
            };
            if (anchorId) {
              const n = postIdToPageNumRef.current.get(anchorId);
              if (typeof n === 'number' && Number.isFinite(n)) {
                setPageInUrl(n);
              }
            }
          } catch { /* noop */ }
        }
      } finally {
        if (!cancelled) {
          document.documentElement.style.scrollBehavior = prevScrollBehavior || '';
          restoringRef.current = false;
        }
        // Schedule neon highlight AFTER all scrolling/restoration is complete
        try {
          const id = anchorId;
          if (id && !isCancelled()) {
            const RESTORE_MS = 850; // keep in sync with CSS --restore-ms
            requestAnimationFrame(() => {
              requestAnimationFrame(() => {
                if (isCancelled()) return;
                const t = findFeedAnchorElement(rootRef.current, `post-${id}`);
                if (t) {
                  t.classList.remove('restore-glow');
                  void t.offsetWidth; // restart animation timeline without layout shifts
                  t.classList.add('restore-glow');
                  setTimeout(() => { try { t.classList.remove('restore-glow'); } catch { } }, RESTORE_MS + 50);
                }
              });
            });
          }
        } catch { /* ignore */ }
      }
    };

    void run().catch(error => { if (!isCancelled()) dlog('restore:error', String(error)); });
    return () => {
      cancelled = true;
      lateObserver?.disconnect();
      if (lateFrame) cancelAnimationFrame(lateFrame);
      if (lateTimeout) clearTimeout(lateTimeout);
      document.documentElement.style.scrollBehavior = prevScrollBehavior || '';
      restoringRef.current = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [storageKeyPrefix, initialPage, layoutReady, virtualizer, loadMore]);
}

// --- Read Status Helpers ---
type ReadMarker = { ts: number; title: string; url?: string };

const readMarkersFromStorage = (): Record<string, ReadMarker> => {
  if (typeof window === 'undefined') return {};
  try {
    const raw = localStorage.getItem(READ_POSTS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object') return {};

    const entries = Object.entries(parsed as Record<string, unknown>);
    const valid = entries.filter(([, value]) => {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
      const marker = value as Partial<ReadMarker>;
      if (typeof marker.ts !== 'number' || typeof marker.title !== 'string') return false;
      if (marker.url !== undefined && typeof marker.url !== 'string') return false;
      return true;
    }) as [string, ReadMarker][];

    const normalized: Record<string, ReadMarker> = {};
    for (const [id, marker] of valid) {
      normalized[id] = marker;
    }
    return normalized;
  } catch {
    return {};
  }
};

const getReadSet = (): Set<string> => new Set(Object.keys(readMarkersFromStorage()));

const areSetsEqual = (a: ReadonlySet<string>, b: ReadonlySet<string>): boolean => {
  if (a === b) return true;
  if (a.size !== b.size) return false;
  for (const value of a) {
    if (!b.has(value)) return false;
  }
  return true;
};

interface ListVirtualizedFeedProps {
  initialPosts: Post[];
  visiblePosts: Post[];
  layout: 'list' | 'grid';
  cardLayoutOverride?: 'grid' | 'list';
  readPostIds: ReadonlySet<string>;
  sectionKey: string;
  listColumns: 'auto-2' | '3-2-1';
  threeColAt: 'lg' | 'xl';
  virtualOverscanOverride?: number;
  loadAheadRowsOverride?: number;
  onBufferSizeChange?: (metrics: VirtualBufferSizing) => void;
  rootRef: React.MutableRefObject<HTMLDivElement | null>;
  loaderRef: React.MutableRefObject<HTMLDivElement | null>;
  colsReadyRef: React.MutableRefObject<boolean>;
  visiblePostsRef: React.MutableRefObject<Post[]>;
  postIdToPageNumRef: React.MutableRefObject<Map<string, number>>;
  hasMoreRef: React.MutableRefObject<boolean>;
  pageRef: React.MutableRefObject<number>;
  seenIdsRef: React.MutableRefObject<Set<string>>;
  restoringRef: React.MutableRefObject<boolean>;
  ensureBelowBufferRows: (anchorId: string) => Promise<void>;
  loadMore: () => Promise<void>;
  hasMore: boolean;
  isFetching: boolean;
  enablePaging: boolean;
  initialPage: number;
  storageKeyPrefix: string;
  urlBootstrapDoneRef: React.MutableRefObject<boolean>;
  lastLoadTriggerRef: React.MutableRefObject<{ rowCount: number; page: number }>;
  isFetchingRef: React.MutableRefObject<boolean>;
  windowScrollMargin: number | 'auto';
  pagingNotice: React.ReactNode;
}

function ListVirtualizedFeed({
  initialPosts,
  visiblePosts,
  layout,
  cardLayoutOverride,
  readPostIds,
  sectionKey,
  listColumns,
  threeColAt,
  virtualOverscanOverride,
  loadAheadRowsOverride,
  onBufferSizeChange,
  rootRef,
  loaderRef,
  colsReadyRef,
  visiblePostsRef,
  postIdToPageNumRef,
  hasMoreRef,
  pageRef,
  seenIdsRef,
  restoringRef,
  ensureBelowBufferRows,
  loadMore,
  hasMore,
  isFetching,
  enablePaging,
  initialPage,
  storageKeyPrefix,
  urlBootstrapDoneRef,
  lastLoadTriggerRef,
  isFetchingRef,
  windowScrollMargin,
  pagingNotice,
}: ListVirtualizedFeedProps) {
  // Instance ID for debugging React Strict Mode double mounting
  const instanceIdRef = useRef(++instanceCounter);

  const [cols, setCols] = useState(1);
  const colsRef = useRef(cols);
  colsRef.current = cols;
  const [containerWidth, setContainerWidth] = useState(0);
  const [hasMounted, setHasMounted] = useState(false);
  const [viewportHeight, setViewportHeight] = useState(() => {
    if (typeof window === 'undefined') return FALLBACK_VIEWPORT_HEIGHT;
    const initial = Math.round(window.innerHeight || FALLBACK_VIEWPORT_HEIGHT);
    return initial > 0 ? initial : FALLBACK_VIEWPORT_HEIGHT;
  });
  const [activePreviewIds, setActivePreviewIds] = useState<Set<string>>(() => new Set());
  const layoutAnchoringRef = useRef(false);
  const pendingLayoutAnchorRef = useRef<{ id: string; top: number; intent: number } | null>(null);
  const [anchoredRow, setAnchoredRow] = useState<number | null>(null);

  useEffect(() => { 
    colsRef.current = cols; 
    if (DEBUG_IPL && cols) {
      dlog(`ListVirtualizedFeed instance #${instanceIdRef.current} initialized`, { 
        initialPage, 
        layout, 
        storageKeyPrefix, 
        enablePaging, 
        initialPostsCount: initialPosts.length,
        cols
      });
    }
  }, [cols, initialPage, layout, storageKeyPrefix, enablePaging, initialPosts.length]);

  useEffect(() => { setHasMounted(true); }, []);

  useEffect(() => {
    const unsubscribe = subscribeToPreviewActivations((ids) => {
      setActivePreviewIds((prev) => (areSetsEqual(prev, ids) ? prev : new Set(ids)));
    });
    return unsubscribe;
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    let raf = 0;
    const update = () => {
      const next = Math.round(window.innerHeight || 0);
      if (next <= 0) {
        setViewportHeight((prev) => (prev > 0 ? prev : FALLBACK_VIEWPORT_HEIGHT));
        return;
      }
      setViewportHeight((prev) => (prev === next ? prev : next));
    };
    update();
    const onResize = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = window.requestAnimationFrame(update);
    };
    window.addEventListener('resize', onResize);
    return () => {
      window.removeEventListener('resize', onResize);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  const estimateCacheRef = useRef<Record<string, number>>({});
  const lastCacheResetKeyRef = useRef<{ cols: number; width: number } | null>(null);
  const getEstimateKey = useCallback(
    (colCount: number) => `${cardLayoutOverride ?? layout}|${Math.max(1, colCount)}`,
    [cardLayoutOverride, layout],
  );

  useEffect(() => {
    const widthKey = Math.round(containerWidth || 0);
    const prev = lastCacheResetKeyRef.current;
    if (!prev || prev.cols !== cols || prev.width !== widthKey) {
      lastCacheResetKeyRef.current = { cols, width: widthKey };
      estimateCacheRef.current = {};
    }
  }, [cols, containerWidth]);

  useEffect(() => {
    if (!hasMounted) return;
    const el = rootRef.current;
    if (!el) return;
    let raf = 0;
    const mqlWide = typeof window !== 'undefined'
      ? window.matchMedia(`(min-width: ${threeColAt === 'xl' ? 1280 : 1024}px)`)
      : null;
    const compute = () => {
      try {
        const w = el.clientWidth || 0;
        setContainerWidth((prev) => (prev === w ? prev : w));
        const GAP = 16; // gap-4
        const MIN_ITEM = 22 * 16; // 22rem
        const maxCols = listColumns === '3-2-1' ? 3 : 2;
        let c = Math.max(1, Math.floor((w + GAP) / (MIN_ITEM + GAP)));
        c = Math.min(c, maxCols);
        if (c >= 3 && listColumns === '3-2-1' && mqlWide && !mqlWide.matches) c = 2;
        if (c !== cols) setCols(c);
        colsReadyRef.current = true;
      } catch { /* noop */ }
    };
    const onResize = () => { if (raf) cancelAnimationFrame(raf); raf = requestAnimationFrame(compute); };
    const ro = new ResizeObserver(onResize);
    ro.observe(el);
    compute();
    return () => { ro.disconnect(); if (raf) cancelAnimationFrame(raf); };
  }, [hasMounted, listColumns, threeColAt, cols, rootRef, colsReadyRef]);

  const rowCount = Math.ceil(visiblePosts.length / Math.max(1, cols));
  const idToIndex = useMemo(() => {
    const map = new Map<string, number>();
    for (let i = 0; i < visiblePosts.length; i++) {
      map.set(visiblePosts[i].id, i);
    }
    return map;
  }, [visiblePosts]);

  const activePreviewRowIndexes = useMemo(() => {
    if (activePreviewIds.size === 0) return [] as number[];
    const colCount = Math.max(1, cols);
    const rows = new Set<number>();
    activePreviewIds.forEach((id) => {
      const idx = idToIndex.get(id);
      if (idx != null) {
        rows.add(Math.floor(idx / colCount));
      }
    });
    if (rows.size === 0) return [] as number[];
    return Array.from(rows).sort((a, b) => a - b);
  }, [activePreviewIds, idToIndex, cols]);
  const estimateRowSize = useCallback(() => {
    const key = getEstimateKey(cols);
    const cached = estimateCacheRef.current[key];
    if (cached && cached > 0) {
      return cached;
    }

    const ROW_GAP = 16;
    const effectiveLayout = cardLayoutOverride ?? layout;
    if (effectiveLayout === 'grid') {
      const w = Math.max(0, containerWidth || (rootRef.current?.clientWidth || 0));
      const c = Math.max(1, cols);
      const gapTotal = (c - 1) * ROW_GAP;
      const cardW = c > 0 ? (w - gapTotal) / c : w;
      const imgH = Math.max(120, Math.round((cardW * 2) / 3));
      const textBlock = 144;
      const estimated = imgH + textBlock + ROW_GAP;
      // Initialize cache with calculated estimate
      estimateCacheRef.current[key] = estimated;
      return estimated;
    }

    const LIST_ROW_BASE = 200;
    const estimated = LIST_ROW_BASE + ROW_GAP;
    // Initialize cache with calculated estimate
    estimateCacheRef.current[key] = estimated;
    return estimated;
  }, [cardLayoutOverride, cols, containerWidth, getEstimateKey, layout, rootRef]);

  const bufferMetrics = useMemo(
    () => {
      const estimated = Number(estimateRowSize());
      return deriveVirtualBufferSizing({
        estimatedRowHeight: estimated,
        viewportHeight,
        overscanOverride: virtualOverscanOverride,
        loadAheadOverride: loadAheadRowsOverride,
      });
    },
    [estimateRowSize, viewportHeight, virtualOverscanOverride, loadAheadRowsOverride],
  );

  useEffect(() => {
    onBufferSizeChange?.(bufferMetrics);
  }, [bufferMetrics, onBufferSizeChange]);

  const readEntryHeight = useCallback((entry: ResizeObserverEntry | undefined): number | null => {
    if (!entry) return null;
    const borderSize = Array.isArray(entry.borderBoxSize) ? entry.borderBoxSize[0] : entry.borderBoxSize;
    if (borderSize && typeof borderSize === 'object' && 'blockSize' in borderSize) {
      const blockSize = Number(borderSize.blockSize);
      if (Number.isFinite(blockSize) && blockSize > 0) return blockSize;
    }
    const height = Number(entry.contentRect?.height ?? 0);
    return Number.isFinite(height) && height > 0 ? height : null;
  }, []);

  const measureRow = useCallback(
    (
      element: Element,
      entry: ResizeObserverEntry | undefined,
      instance: Virtualizer<Window, Element>,
    ) => {
      const key = getEstimateKey(colsRef.current);
      const cached = estimateCacheRef.current[key];
      const entryHeight = readEntryHeight(entry);
      const TOLERANCE = 4;

      let size: ReturnType<typeof defaultMeasureElement>;
      if (
        typeof cached === 'number'
        && Number.isFinite(cached)
        && cached > 0
        && typeof entryHeight === 'number'
        && Math.abs(entryHeight - cached) <= TOLERANCE
      ) {
        size = entryHeight;
      } else {
        size = defaultMeasureElement(element, entry, instance);
      }

      if (typeof size === 'number' && Number.isFinite(size) && size > 0) {
        const prev = estimateCacheRef.current[key];
        const next = prev ? Math.round(prev * 0.6 + size * 0.4) : Math.round(size);
        if (!prev || Math.abs(prev - next) > 1) {
          estimateCacheRef.current[key] = next;
        }
      }
      return size;
    },
    [getEstimateKey, readEntryHeight],
  );

  const rangeExtractor = useCallback(
    (range: Range) => {
      const base = defaultRangeExtractor(range);
      if (activePreviewRowIndexes.length === 0 && anchoredRow == null) {
        return base;
      }
      const merged = new Set(base);
      if (anchoredRow != null && anchoredRow < range.count) merged.add(anchoredRow);
      for (const rowIndex of activePreviewRowIndexes) {
        if (rowIndex >= 0 && rowIndex < range.count) {
          merged.add(rowIndex);
        }
      }
      if (merged.size === base.length) {
        return base;
      }
      return Array.from(merged).sort((a, b) => a - b);
    },
    [activePreviewRowIndexes, anchoredRow],
  );

  const feedPosition = useFeedScrollMargin(rootRef, windowScrollMargin, restoringRef, layoutAnchoringRef);
  const { margin: effectiveScrollMargin, ready: positionReady, anchorRef, userIntentRef, captureAnchor } = feedPosition;
  const virtualizer = useWindowVirtualizer({
    count: rowCount,
    estimateSize: estimateRowSize,
    overscan: bufferMetrics.overscanRows,
    measureElement: measureRow,
    getItemKey: (row) => {
      const idx0 = row * cols;
      return visiblePosts[idx0]?.id ?? row;
    },
    rangeExtractor,
    scrollMargin: effectiveScrollMargin,
  });

  // Only a changed row layout invalidates measured sizes. Position changes and
  // appended rows are handled by the virtualizer without clearing earlier rows.
  const measuredLayoutRef = useRef<string | null>(null);
  const previousFeedIdsRef = useRef<string[]>([]);
  useLayoutEffect(() => {
    if (!positionReady || !containerWidth) return;
    const key = `${cardLayoutOverride ?? layout}|${cols}|${containerWidth}`;
    const previous = measuredLayoutRef.current;
    const nextIds = visiblePosts.map(post => post.id);
    const previousIds = previousFeedIdsRef.current;
    const reordered = previousIds.length > nextIds.length || previousIds.some((id, index) => nextIds[index] !== id);
    previousFeedIdsRef.current = nextIds;
    if (previous === key && !reordered && !pendingLayoutAnchorRef.current) return;
    measuredLayoutRef.current = key;
    if (window.scrollY <= 0.5) {
      anchorRef.current = null;
      pendingLayoutAnchorRef.current = null;
      layoutAnchoringRef.current = false;
      virtualizer.shouldAdjustScrollPositionOnItemSizeChange = undefined;
      setAnchoredRow(null);
      if (previous !== key) virtualizer.measure();
      return;
    }
    if (pendingLayoutAnchorRef.current && pendingLayoutAnchorRef.current.intent !== userIntentRef.current) {
      pendingLayoutAnchorRef.current = null;
      layoutAnchoringRef.current = false;
      virtualizer.shouldAdjustScrollPositionOnItemSizeChange = undefined;
      setAnchoredRow(null);
      if (previous !== key) virtualizer.measure();
      captureAnchor();
      return;
    }
    const previousAnchor = pendingLayoutAnchorRef.current ?? anchorRef.current;
    const survivingId = findSurvivingFeedAnchor(previousIds, new Set(nextIds), previousAnchor?.id.replace(/^post-/, '') ?? null);
    const anchor = previousAnchor && survivingId ? { id: `post-${survivingId}`, top: previousAnchor.top } : null;
    const intent = userIntentRef.current;
    if (!previous || !anchor || restoringRef.current) {
      pendingLayoutAnchorRef.current = null;
      layoutAnchoringRef.current = false;
      virtualizer.shouldAdjustScrollPositionOnItemSizeChange = undefined;
      setAnchoredRow(null);
      if (previous !== key) virtualizer.measure();
      return;
    }
    const index = visiblePosts.findIndex(post => `post-${post.id}` === anchor.id);
    if (index < 0) return;
    const row = Math.floor(index / Math.max(1, cols));
    pendingLayoutAnchorRef.current = { ...anchor, intent };
    layoutAnchoringRef.current = true;
    // DOM anchoring owns these corrections. The normal measured-size scroller
    // resumes once this layout has settled or the reader cancels it.
    virtualizer.shouldAdjustScrollPositionOnItemSizeChange = () => false;
    setAnchoredRow(row);
    if (previous !== key) virtualizer.measure();
    scrollToFeedRow(virtualizer, row);
    let frame = 0;
    let attempts = 0;
    let stableFrames = 0;
    const finish = () => {
      pendingLayoutAnchorRef.current = null;
      layoutAnchoringRef.current = false;
      virtualizer.shouldAdjustScrollPositionOnItemSizeChange = undefined;
      setAnchoredRow(null);
      captureAnchor();
    };
    const correct = () => {
      if (window.scrollY <= 0.5 || restoringRef.current || userIntentRef.current !== intent) { finish(); return; }
      const element = findFeedAnchorElement(rootRef.current, anchor.id);
      const delta = element ? element.getBoundingClientRect().top - anchor.top : Infinity;
      if (rootRef.current && correctFeedViewportAnchor(rootRef.current, anchor)) {
        stableFrames = Math.abs(delta) <= 0.5 ? stableFrames + 1 : 0;
      } else {
        stableFrames = 0;
      }
      if (stableFrames >= 8 || ++attempts >= 60) { finish(); return; }
      frame = requestAnimationFrame(correct);
    };
    frame = requestAnimationFrame(correct);
    return () => cancelAnimationFrame(frame);
  }, [anchorRef, captureAnchor, cardLayoutOverride, cols, containerWidth, layout, positionReady, restoringRef, rootRef, userIntentRef, virtualizer, visiblePosts]);

  useEffect(() => () => {
    layoutAnchoringRef.current = false;
    virtualizer.shouldAdjustScrollPositionOnItemSizeChange = undefined;
  }, [virtualizer]);

  useEffect(() => {
    if (!DEBUG_IPL) return;
    try {
      const w = window as typeof window & {
        __VLIST__?: { scrollToIndex: (index: number) => void };
        __LIST_COLS__?: string;
        __VLIST_BUFFERS__?: VirtualBufferSizing;
      };
      w.__VLIST__ = { scrollToIndex: (i: number) => virtualizer.scrollToIndex(i) };
      w.__LIST_COLS__ = String(cols);
      w.__VLIST_BUFFERS__ = bufferMetrics;
    } catch { /* no-op */ }
  }, [virtualizer, cols, bufferMetrics]);

  const items = virtualizer.getVirtualItems();
  const layoutReady = positionReady && containerWidth > 0 && colsReadyRef.current;

  useEffect(() => {
    if (restoringRef.current) return;
    if (!enablePaging || !hasMoreRef.current) return;
    const last = items[items.length - 1];
    if (!last) return;
    const range = virtualizer.range;
    const viewportStart = Math.max(0, range?.startIndex ?? items[0]?.index ?? 0);
    const viewportEnd = Math.max(viewportStart, range?.endIndex ?? last.index);
    const manualTail = loadAheadRowsOverride != null ? Math.max(1, Math.round(loadAheadRowsOverride)) : null;
    const derivedTail = Math.max(1, bufferMetrics.loadAheadRows);
    const desiredTail = manualTail ?? derivedTail;
    // Smart threshold: trigger when approaching the end minus buffer size
    // This ensures smooth scrolling while preventing premature loading
    const threshold = Math.max(0, rowCount - desiredTail);
    const inTail = viewportEnd >= threshold;

    if (DEBUG_IPL) {
      dlog(`infinite-scroll:check (instance #${instanceIdRef.current})`, {
        sectionKey,
        viewportEnd,
        threshold,
        rowCount,
        visiblePostsLength: visiblePosts.length,
        seenIdsSize: seenIdsRef.current.size,
        desiredTail,
        inTail,
        isFetching: isFetchingRef.current,
        hasMore: hasMoreRef.current,
      });
    }

    if (!inTail) return;

    const prev = lastLoadTriggerRef.current;
    const cur = { rowCount, page: pageRef.current };
    if (prev.rowCount === cur.rowCount && prev.page === cur.page) {
      return;
    }
    lastLoadTriggerRef.current = cur;

    if (!isFetchingRef.current) {
      if (DEBUG_IPL) {
        dlog('infinite-scroll:trigger-load', { viewportEnd, threshold, rowCount, page: pageRef.current });
      }
      loadMore();
    }
  }, [
    items,
    rowCount,
    enablePaging,
    loadMore,
    loadAheadRowsOverride,
    restoringRef,
    hasMoreRef,
    pageRef,
    lastLoadTriggerRef,
    isFetchingRef,
    virtualizer,
    bufferMetrics.loadAheadRows,
  ]);

  useEffect(() => {
    let prev: ScrollRestoration | null = null;
    try {
      const history = window.history as History & { scrollRestoration?: ScrollRestoration };
      prev = history.scrollRestoration ?? null;
      history.scrollRestoration = 'manual';
    } catch { /* ignore */ }
    return () => {
      try {
        const history = window.history as History & { scrollRestoration?: ScrollRestoration };
        history.scrollRestoration = prev ?? 'auto';
      } catch { /* ignore */ }
    };
  }, []);

  useRestoreFromDetail({
    storageKeyPrefix,
    initialPage,
    cols,
    layoutReady,
    userIntentRef,
    virtualizer,
    loadMore,
    hasMoreRef,
    pageRef,
    colsReadyRef,
    visiblePostsRef,
    seenIdsRef,
    postIdToPageNumRef,
    rootRef,
    restoringRef,
    ensureBelowBufferRows,
  });

  useEffect(() => {
    if (!enablePaging || !layoutReady) return;
    if (restoringRef.current) return;
    if (urlBootstrapDoneRef.current) return;
    urlBootstrapDoneRef.current = true;

    const pStr = typeof window !== 'undefined'
      ? new URL(window.location.href).searchParams.get('page')
      : null;
    const target = pStr ? Math.max(1, parseInt(pStr, 10) || 1) : 1;
    if (target <= 1) return;

    let cancelled = false;
    const initialIntent = userIntentRef.current;
    const isCancelled = () => cancelled || userIntentRef.current !== initialIntent;
    const prevScrollBehavior = document.documentElement.style.scrollBehavior;
    document.documentElement.style.scrollBehavior = 'auto';
    restoringRef.current = true;
    const waitFrames = (n: number) => new Promise<void>((res) => {
      let i = 0;
      const step = () => {
        if (isCancelled()) return res();
        if (++i >= n) return res();
        requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    });

    const run = async () => {
      try {
      while (pageRef.current < target && hasMoreRef.current && !isCancelled()) {
        await loadMore();
        await waitFrames(1);
      }
      const requestedId = Array.from(postIdToPageNumRef.current).find(([, page]) => page === target)?.[0];
      for (let attempt = 0; requestedId && attempt < 60 && !isCancelled(); attempt++) {
        if (visiblePostsRef.current.some(post => post.id === requestedId)) break;
        await waitFrames(1);
      }

      const findAnchorOnTarget = () => {
        const list = visiblePostsRef.current;
        for (let i = 0; i < list.length; i++) {
          const id = list[i].id;
          const pn = postIdToPageNumRef.current.get(id);
          if ((pn ?? 1) === target) return id;
        }
        for (let i = 0; i < list.length; i++) {
          const id = list[i].id;
          const pn = postIdToPageNumRef.current.get(id) ?? 1;
          if (pn > target) return id;
        }
        for (let i = list.length - 1; i >= 0; i--) {
          const id = list[i].id;
          const pn = postIdToPageNumRef.current.get(id) ?? 1;
          if (pn < target) return id;
        }
        return list[0]?.id ?? null;
      };

      let anchorId: string | null = findAnchorOnTarget();
      let guard = 0;
      while (!anchorId && hasMoreRef.current && guard < 4 && !isCancelled()) {
        guard++;
        await loadMore();
        await waitFrames(1);
        anchorId = findAnchorOnTarget();
      }
      if (isCancelled()) return;

      if (anchorId) {
        const idx = visiblePostsRef.current.findIndex((p) => p.id === anchorId);
        if (idx >= 0) {
          const rowIndex = Math.floor(idx / Math.max(1, colsRef.current));
          try {
            scrollToFeedRow(virtualizer, rowIndex);
          } catch { /* ignore */ }
          await waitFrames(1);
        }
        if (isCancelled()) return;
        let el: HTMLElement | null = null;
        for (let attempt = 0; attempt < 60 && !isCancelled(); attempt++) {
          el = findFeedAnchorElement(rootRef.current, `post-${anchorId}`);
          if (el) break;
          await waitFrames(1);
        }
        if (isCancelled()) return;
        if (el) {
          el.scrollIntoView({ behavior: 'auto', block: 'start' });
        }
        await ensureBelowBufferRows(anchorId);
      }
      if (isCancelled()) return;

      try {
        const setPageInUrl = (n: number) => {
          const u = new URL(window.location.href);
          if (n <= 1) u.searchParams.delete('page'); else u.searchParams.set('page', String(n));
          const qs = u.searchParams.toString();
          window.history.replaceState(null, '', u.pathname + (qs ? `?${qs}` : '') + u.hash);
        };
        if (anchorId) {
          const n = postIdToPageNumRef.current.get(anchorId);
          if (typeof n === 'number' && Number.isFinite(n)) setPageInUrl(n);
          else setPageInUrl(target);
        } else {
          setPageInUrl(target);
        }
      } catch { /* ignore */ }
      } finally {
        if (!cancelled) {
          document.documentElement.style.scrollBehavior = prevScrollBehavior || '';
          restoringRef.current = false;
        }
      }
    };

    void run().catch(error => dlog('page-restore:error', error instanceof Error ? error.message : String(error)));
    return () => {
      cancelled = true;
      document.documentElement.style.scrollBehavior = prevScrollBehavior || '';
      restoringRef.current = false;
    };
  }, [enablePaging, layoutReady, loadMore, virtualizer, restoringRef, rootRef, urlBootstrapDoneRef, pageRef, hasMoreRef, ensureBelowBufferRows, postIdToPageNumRef, userIntentRef, visiblePostsRef]);

  return (
    <>
      <style jsx global>{`
        /* Restore neon glow effect for the post anchor on return from detail */
        .post-anchor.restore-glow { --restore-ms: 850ms; }
        .post-anchor { position: relative; }
        .post-anchor.restore-glow::after,
        .post-anchor.restore-glow::before { content: ""; position: absolute; inset: 0; border-radius: 12px; pointer-events: none; }

        /* Dim the content briefly so the neon ring pops on light backgrounds */
        .post-anchor.restore-glow::before {
          background: #000;
          opacity: 0;
          z-index: 2; /* above children */
          animation: restore-dim var(--restore-ms) ease-out forwards;
        }

        /* Rainbow neon ring that swirls once around the card and fades out */
        .post-anchor.restore-glow::after {
          z-index: 3; /* top-most */
          padding: 2px; /* ring thickness */
          border-radius: 14px; /* slightly larger than card corners */
          background: conic-gradient(
            from 0turn,
            #ff0066, #ff8a00, #ffdc00, #00e676, #00b0ff, #8e24aa, #ff0066
          );
          -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          -webkit-mask-composite: xor;
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask-composite: exclude;
          filter: saturate(1.6) brightness(1.2) blur(0.2px);
          box-shadow: 0 0 18px rgba(255,255,255,0.18);
          will-change: filter, opacity;
          animation: hue-spin var(--restore-ms) linear forwards,
                     ring-fade var(--restore-ms) ease-out forwards;
        }

        @keyframes hue-spin { from { filter: hue-rotate(0deg); } to { filter: hue-rotate(360deg); } }
        @keyframes ring-fade { from { opacity: 1; } to { opacity: 0; } }
        @keyframes restore-dim {
          0% { opacity: 0; }
          10% { opacity: .32; }
          30% { opacity: .18; }
          55% { opacity: .26; }
          100% { opacity: 0; }
        }

        @media (prefers-reduced-motion: reduce) {
          .post-anchor.restore-glow::after, .post-anchor.restore-glow::before { animation: none !important; opacity: 0 !important; }
        }
      `}</style>
      <div ref={rootRef} data-virtual-feed data-scroll-margin={effectiveScrollMargin} data-layout-ready={layoutReady}>
        <div style={{ height: virtualizer.getTotalSize(), width: '100%', position: 'relative' }}>
          {items.map((vi) => {
            const start = vi.index * cols;
            const rowPosts = visiblePosts.slice(start, start + cols);
            if (rowPosts.length === 0) return null;
            return (
              <div
                key={`row-${vi.index}-${rowPosts[0].id}`}
                ref={virtualizer.measureElement}
                data-index={vi.index}
                style={{ position: 'absolute', top: 0, left: 0, width: '100%', transform: `translate3d(0, ${virtualRowOffset(vi.start, effectiveScrollMargin)}px, 0)`, willChange: 'transform' }}
              >
                <div
                  className="grid gap-4"
                  style={{ gridTemplateColumns: `repeat(${Math.max(1, cols)}, minmax(0, 1fr))` }}
                >
                  {rowPosts.map((post, i) => (
                    <div
                      key={post.id}
                      id={`post-${post.id}`}
                      className="post-anchor relative isolate"
                      style={{ scrollMarginTop: 'var(--sticky-top, 0px)' }}
                    >
                      {(() => {
                        const indexGlobal = start + i;
                        const pageNum = postIdToPageNumRef.current.get(post.id) || initialPage;
                        const prevId = visiblePosts[indexGlobal - 1]?.id;
                        const prevPage = prevId ? postIdToPageNumRef.current.get(prevId) : undefined;
                        const isPageStart = indexGlobal === 0 || pageNum !== prevPage;
                        return isPageStart ? (
                          <div data-page-sentinel={pageNum} aria-hidden="true" style={{ display: 'block', height: 1 }} />
                        ) : null;
                      })()}
                      <PostCard
                        postId={post.id}
                        layout={cardLayoutOverride ?? layout}
                        page={postIdToPageNumRef.current.get(post.id) || initialPage}
                        storageKeyPrefix={storageKeyPrefix}
                        sectionKey={sectionKey}
                        isNew={(start + i) >= initialPosts.length}
                        isPriority={(start + i) < 5}
                        isRead={readPostIds.has(post.id)}
                      />
                    </div>
                  ))}
                </div>
                <div className="h-4" aria-hidden />
              </div>
            );
          })}
        </div>

        {enablePaging && <div ref={loaderRef} aria-label="infinite-loader" className="h-1" />}
        {isFetching && hasMore && (
          <div className="text-center text-gray-400 py-4">불러오는 중...</div>
        )}
        {pagingNotice}
      </div>
    </>
  );
}

interface InfinitePostListProps {
  initialPosts: Post[];
  excludedPostIds?: string[];
  initialPage?: number;
  layout?: "list" | "grid";
  jsonBase?: string;
  storageKeyPrefix?: string;
  enablePaging?: boolean;
  community?: string;
  onColsChange?: (n: number) => void;
  readFilter?: string;
  /**
   * Optional offset applied when virtualizing against the window scroller. When set to "auto",
   * the list measures its distance from the top of the document to keep scroll positions stable
   * with sticky headers.
   */
  windowScrollMargin?: 'auto' | number;
  /**
   * Virtualized list column mode.
   * - 'auto-2': 1 → 2 columns at md breakpoint (default)
   * - '3-2-1': 1 → 2 → 3 columns at md/lg breakpoints
   */
  listColumns?: 'auto-2' | '3-2-1';
  /**
   * When using list virtualization, render cards using this layout style.
   * Useful for category pages wanting grid-style cards with virtualized loading.
   */
  cardLayoutOverride?: 'grid' | 'list';
  /**
   * Breakpoint for 3 columns when listColumns='3-2-1'. Default 'lg' (1024). Set 'xl' for 1280.
   */
  threeColAt?: 'lg' | 'xl';
  /**
   * Force grid column count for layout="grid" path. When set, overrides auto-fit.
   */
  gridColumnsOverride?: number;
  /**
   * Optional override for the derived tail buffer. The list now derives a
   * symmetric ~0.5 viewport warmup automatically, so manual overrides are
   * rarely necessary.
   */
  loadAheadRows?: number;
  /**
   * Optional override for the derived overscan rows. When omitted the list
   * keeps roughly half a viewport of posts rendered before and after the
   * window.
   */
  virtualOverscan?: number;
}

export default function InfinitePostList({
  initialPosts,
  excludedPostIds,
  initialPage = 1,
  layout = "list",
  jsonBase,
  storageKeyPrefix = "",
  enablePaging = true,
  community,
  onColsChange,
  listColumns = 'auto-2',
  cardLayoutOverride,
  threeColAt = 'lg',
  gridColumnsOverride,
  loadAheadRows,
  virtualOverscan,
  readFilter = 'all',
  windowScrollMargin: windowScrollMarginProp = 'auto',
}: InfinitePostListProps) {
  const { addPostsToSection, replacePostsForSection } = usePostCache();
  const searchParams = useSearchParams();
  // --- Column change observer (for grid layout) ---
  const prevColsRef = useRef<number>(0);
  useEffect(() => {
    if (!onColsChange || layout !== 'grid') return;
    const el = rootRef.current;
    if (!el) return;

    const compute = () => {
      try {
        const cs = window.getComputedStyle(el);
        const cols = (cs.gridTemplateColumns || '').split(' ').filter(Boolean).length || 1;
        const next = Math.max(1, cols);
        if (prevColsRef.current !== next) {
          prevColsRef.current = next;
          onColsChange(next);
        }
      } catch { }
    };

    let raf = 0;
    const onResize = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        compute();
      });
    };
    const ro = new window.ResizeObserver(onResize);
    ro.observe(el);
    compute();
    return () => { ro.disconnect(); if (raf) cancelAnimationFrame(raf); };
  }, [onColsChange, layout]);

  // Instance ID for debugging React Strict Mode double mounting
  const instanceIdRef = useRef(++instanceCounter);

  useEffect(() => {
    dlog(`InfinitePostList instance #${instanceIdRef.current} mount`, { 
      initialPage, 
      layout, 
      jsonBase, 
      storageKeyPrefix, 
      enablePaging, 
      community,
      initialPostsCount: initialPosts.length
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- State & Refs ---
  const [posts, setPosts] = useState<Post[]>(initialPosts);
  const [page, setPage] = useState(initialPage);
  const [hasMore, setHasMore] = useState(Boolean(enablePaging && jsonBase));
  const [newVersionAvailable, setNewVersionAvailable] = useState(false);
  const newVersionAvailableRef = useRef(false);
  const [loadError, setLoadError] = useState(false);
  const excludedIdsRef = useRef(new Set(excludedPostIds));
  const loadedGenerationRef = useRef<string | null>(null);
  const seedPostsRef = useRef(initialPosts);
  const seedIdsRef = useRef(new Set(initialPosts.map(post => post.id)));
  // --- Live postsRef for up-to-date list ---
  const postsRef = useRef(posts);
  useEffect(() => { postsRef.current = posts; }, [posts]);
  // Refs to observe page/hasMore changes during async restore
  const pageRef = useRef(page);
  useEffect(() => { pageRef.current = page; }, [page]);
  const hasMoreRef = useRef(hasMore);
  const urlBootstrapDoneRef = useRef(false);
  useEffect(() => { hasMoreRef.current = hasMore; }, [hasMore]);
  // Gating: avoid re-triggering loadMore for the same (rowCount,page) tail state
  const lastLoadTriggerRef = useRef<{ rowCount: number; page: number }>({ rowCount: -1, page: -1 });
  // Tracks the latest visiblePosts snapshot during restore (already exists below)
  // Tracks when columns have been measured at least once
  const colsReadyRef = useRef(false);

  // Guard to ensure we run restore only once
  const restoringRef = useRef(false);
  const loaderRef = useRef<HTMLDivElement | null>(null);
  const isFetchingRef = useRef(false);
  const fetchTokenRef = useRef(0);
  const bufferMetricsRef = useRef<VirtualBufferSizing>(
    deriveVirtualBufferSizing({ estimatedRowHeight: FALLBACK_ROW_ESTIMATE, viewportHeight: FALLBACK_VIEWPORT_HEIGHT }),
  );
  const handleBufferSizeChange = useCallback((metrics: VirtualBufferSizing) => {
    bufferMetricsRef.current = metrics;
  }, []);
  const seenIdsRef = useRef<Set<string>>(new Set(initialPosts.map((p) => p.id)));
  const postIdToPageNumRef = useRef<Map<string, number>>(
    new Map(initialPosts.map((p) => [p.id, initialPage]))
  );
  const recentFailRef = useRef<Map<number, number>>(new Map());
  const missingStreakRef = useRef(0);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [isFetching, setIsFetching] = useState(false);
  const [activeCommunity, setActiveCommunity] = useState<string>(community ?? "전체");
  const [activeCommunities, setActiveCommunities] = useState<string[] | null>(null); // null => 전체
  const [readPostIds, setReadPostIds] = useState(() => getReadSet());

  // Community filtering is view-only; section reset is keyed only by base.
  const sectionKey = useMemo(
    () => `${jsonBase}|${storageKeyPrefix}`,
    [jsonBase, storageKeyPrefix]
  );
  const prevSectionKeyRef = useRef(sectionKey);
  const sectionEpochRef = useRef(0);
  const currentAbortRef = useRef<AbortController | null>(null);
  const manifestRef = useRef<ManifestSnapshot | null>(null);
  const manifestFetchTimeRef = useRef<number | null>(null);
  const prefetchingRef = useRef<Set<string>>(new Set());
  useEffect(() => () => {
    sectionEpochRef.current += 1;
    fetchTokenRef.current += 1;
    currentAbortRef.current?.abort();
    isFetchingRef.current = false;
    lastLoadTriggerRef.current = { rowCount: -1, page: -1 };
  }, []);

  const maybeRefreshManifest = useCallback(
    async (base: string | null | undefined) => {
      const epoch = sectionEpochRef.current;
      const isCurrent = () => sectionEpochRef.current === epoch && prevSectionKeyRef.current === sectionKey;
      if (!isCurrent()) return { manifest: null, versionChanged: false };
      if (!base) {
        return { manifest: manifestRef.current, versionChanged: false };
      }

      const now = Date.now();
      const prev = manifestRef.current;
      const lastFetchedAt = prev?.fetchedAt ?? manifestFetchTimeRef.current;
      if (lastFetchedAt && now - lastFetchedAt < MANIFEST_TTL_MS) {
        return { manifest: prev, versionChanged: false };
      }

      const manifest = await cacheGetManifest(base);
      if (!isCurrent()) return { manifest: null, versionChanged: false };
      const fetchedAt = Date.now();
      manifestFetchTimeRef.current = fetchedAt;
      const maybeLastPage = (manifest as Record<string, unknown>)?.lastPage;

      if (manifest?.generatedAt) {
        const next = {
          generatedAt: manifest.generatedAt,
          lastPage: typeof maybeLastPage === "number" ? maybeLastPage : undefined,
          hasMore: typeof manifest.hasMore === 'boolean' ? manifest.hasMore : undefined,
          seedPolicy: typeof manifest.seedPolicy === 'string' ? manifest.seedPolicy : undefined,
          fetchedAt,
        };
        const versionChanged = !prev || prev.generatedAt !== next.generatedAt;
        manifestRef.current = next;
        return { manifest: next, versionChanged };
      }

      const versionChanged = Boolean(prev?.generatedAt);
      manifestRef.current = null;
      return { manifest: null, versionChanged };
    },
    [sectionKey],
  );

  const stopForNewGeneration = useCallback(() => {
    newVersionAvailableRef.current = true;
    setNewVersionAvailable(true);
    hasMoreRef.current = false;
    setHasMore(false);
  }, []);

  useLayoutEffect(() => {
    const prevKey = prevSectionKeyRef.current;
    if (prevKey === sectionKey) {
      const nextExcluded = new Set(excludedPostIds);
      if (loadedGenerationRef.current && !areSetsEqual(excludedIdsRef.current, nextExcluded)) {
        stopForNewGeneration();
        return;
      }
      excludedIdsRef.current = nextExcluded;
      if (seedPostsRef.current !== initialPosts) {
        const changedIds = seedPostsRef.current.length !== initialPosts.length || seedPostsRef.current.some((post, index) => post.id !== initialPosts[index]?.id);
        if (loadedGenerationRef.current && changedIds) {
          stopForNewGeneration();
          return;
        }
        const next = reconcileFeedSeed({
          currentPosts: postsRef.current,
          previousSeedIds: seedIdsRef.current,
          nextSeed: initialPosts,
          postIdToPageNum: postIdToPageNumRef.current,
          currentPage: pageRef.current,
          currentHasMore: hasMoreRef.current,
          initialPage,
        });
        seedPostsRef.current = initialPosts;
        seedIdsRef.current = next.seedIds;
        seenIdsRef.current = next.seenIds;
        postIdToPageNumRef.current = next.postIdToPageNum;
        postsRef.current = next.posts;
        setPosts(next.posts);
        replacePostsForSection(sectionKey, next.posts);
        lastLoadTriggerRef.current = { rowCount: -1, page: -1 };
      } else {
        replacePostsForSection(sectionKey, postsRef.current);
      }
      return;
    }

    prevSectionKeyRef.current = sectionKey;
    sectionEpochRef.current += 1;

    dlog("section-change", {
      from: prevKey,
      to: sectionKey,
      initialPage,
      initialCount: initialPosts.length,
    });

    currentAbortRef.current?.abort();
    currentAbortRef.current = null;
    fetchTokenRef.current += 1;

    manifestRef.current = null;
    loadedGenerationRef.current = null;
    excludedIdsRef.current = new Set(excludedPostIds);
    newVersionAvailableRef.current = false;
    setNewVersionAvailable(false);
    setLoadError(false);
    manifestFetchTimeRef.current = null;
    prefetchingRef.current = new Set();
    recentFailRef.current = new Map();
    missingStreakRef.current = 0;

    const baselinePosts = [...initialPosts];
    seedPostsRef.current = initialPosts;
    seedIdsRef.current = new Set(initialPosts.map(post => post.id));
    postsRef.current = baselinePosts;
    setPosts(baselinePosts);
    replacePostsForSection(sectionKey, baselinePosts);

    const baselinePage = initialPage;
    pageRef.current = baselinePage;
    setPage(baselinePage);

    const nextHasMore = Boolean(enablePaging && jsonBase);
    hasMoreRef.current = nextHasMore;
    setHasMore(nextHasMore);

    seenIdsRef.current = new Set(initialPosts.map((p) => p.id));
    postIdToPageNumRef.current = new Map(initialPosts.map((p) => [p.id, baselinePage]));

    isFetchingRef.current = false;
    setIsFetching(false);

    lastLoadTriggerRef.current = { rowCount: -1, page: -1 };
    urlBootstrapDoneRef.current = false;
  }, [
    enablePaging,
    excludedPostIds,
    initialPage,
    initialPosts,
    jsonBase,
    replacePostsForSection,
    sectionKey,
    stopForNewGeneration,
  ]);

  useEffect(() => {
    if (!enablePaging || !jsonBase) return;

    const key = `prime|${jsonBase}`;
    const warmSet = prefetchingRef.current;
    if (warmSet.has(key)) return;

    const abortController = new AbortController();
    const { signal } = abortController;
    warmSet.add(key);

    (async () => {
      try {
        const { manifest, versionChanged } = await maybeRefreshManifest(jsonBase);
        if (signal.aborted) return;

        if (manifest?.generatedAt && manifest.hasMore !== false && manifest.lastPage !== 1) {
          let cached: ClientPost[] | null = null;
          if (!versionChanged) {
            try {
              cached = await cacheReadPage(jsonBase, FIRST_JSON_PAGE, manifest.generatedAt);
            } catch {
              cached = null;
            }
          }
          if (signal.aborted) return;

          if (!cached || cached.length === 0) {
            try {
              const res = await fetch(`${jsonBase}/page-${FIRST_JSON_PAGE}.json`, { signal });
              if (!res.ok || signal.aborted) return;

              const data = await res.json();
              if (signal.aborted) return;
              if ((manifest.seedPolicy === 'live-seed-dedupe' || typeof data.generatedAt === 'string') && data.generatedAt !== manifest.generatedAt) return;

              const arr = (Array.isArray(data.posts) ? data.posts : []) as Post[];
              const normalized = arr.map((p: Post & { community?: string; site?: string }) => ({
                ...p,
                communityId: p.communityId || p.community || p.site || undefined,
                communityLabel: p.communityLabel || p.community || p.site || undefined,
              })) as Post[];

              if (signal.aborted) return;
              await cacheWritePage(
                jsonBase,
                FIRST_JSON_PAGE,
                manifest.generatedAt,
                normalized as unknown as ClientPost[]
              );
            } catch {
              /* ignore */
            }
          }
        }
      } catch {
        /* ignore */
      } finally {
        warmSet.delete(key);
      }
    })();

    return () => {
      abortController.abort();
      warmSet.delete(key);
    };
  }, [enablePaging, jsonBase, maybeRefreshManifest]);
  // Expose minimal navigation API for modal to query sequence and request more
  const navRegistryKey = jsonBase || storageKeyPrefix || "__default__";
  const navApiRef = useRef<FeedNavigationApi | null>(null);

  useEffect(() => {
    if (community !== undefined) {
      setActiveCommunity(community || "전체");
      setActiveCommunities(null);
      return;
    }
    const off1 = onCommunity((v) => {
      setActiveCommunities(null);
      setActiveCommunity(v || "전체");
    });
    const off2 = onCommunities((ids) => {
      if (ids && ids.length > 0) {
        setActiveCommunity(ids.length === 1 ? ids[0] : "전체");
        setActiveCommunities([...ids]);
      } else {
        // null or empty => 전체
        setActiveCommunity("전체");
        setActiveCommunities(null);
      }
    });
    return () => { off1(); off2(); };
  }, [community]);

  // No resume/restore or user-interaction gating.

  // --- Core Data Fetching ---
  const loadPage = useCallback(
    async (pageNum: number, signal?: AbortSignal): Promise<LoadResult> => {
      const epoch = sectionEpochRef.current;
      const isCurrent = () => !signal?.aborted && sectionEpochRef.current === epoch && prevSectionKeyRef.current === sectionKey;
      if (!isCurrent()) return { status: 'error', newPosts: [] };
      // Community does not affect network base; it is a pure client-side filter.
      const base = jsonBase;
      if (!base) return { status: "missing", newPosts: [] };
      dlog("loadPage:start", { pageNum, url: `${base}/page-${pageNum}.json` });

      const url = `${base}/page-${pageNum}.json`;

      const { manifest, versionChanged } = await maybeRefreshManifest(base);
      if (!isCurrent()) return { status: 'error', newPosts: [] };
      const generation = manifest?.generatedAt;
      if (loadedGenerationRef.current && generation && loadedGenerationRef.current !== generation) {
        stopForNewGeneration();
        return { status: 'error', newPosts: [] };
      }

      if (Date.now() - (recentFailRef.current.get(pageNum) ?? 0) < FAILED_PAGE_RETRY_WINDOW) {
        return { status: "error", newPosts: [] };
      }

      // 1) Try IndexedDB cache (if manifest/version available)
      if (generation && !versionChanged) {
        try {
          const cached = await cacheReadPage(base, pageNum, generation);
          if (!isCurrent()) return { status: 'error', newPosts: [] };
          if (cached && cached.length >= 0) {
            loadedGenerationRef.current = generation ?? loadedGenerationRef.current;
            const uniques = cached.filter((p) => !seenIdsRef.current.has(p.id) && !excludedIdsRef.current.has(p.id));
            dlog("loadPage:cache-hit", { pageNum, cachedCount: cached.length, uniques: uniques.length });
            return { status: uniques.length > 0 ? "ok-new" : "ok-dup", newPosts: uniques as unknown as Post[] };
          }
        } catch { /* ignore */ }
      }

      // 2) Network with retries
      for (let i = 0; i <= RETRY_BACKOFFS.length; i++) {
        try {
          const res = await fetch(url, { signal });
          if (!isCurrent()) return { status: 'error', newPosts: [] };
          if (res.status === 404) {
            dlog("loadPage:404", { pageNum });
            recentFailRef.current.set(pageNum, Date.now());
            return { status: "missing", newPosts: [] };
          }
          if (!res.ok) throw new Error(`HTTP ${res.status}`);

          const data = await res.json();
          if (!isCurrent()) return { status: 'error', newPosts: [] };
          if (generation && (manifest.seedPolicy === 'live-seed-dedupe' || typeof data.generatedAt === 'string') && data.generatedAt !== generation) {
            stopForNewGeneration();
            return { status: 'error', newPosts: [] };
          }
          const incomingRaw = (Array.isArray(data.posts) ? data.posts : []) as Post[];
          // Normalize community fields for filtering/display
          const incoming = incomingRaw.map((p: Post & { community?: string; site?: string }) => ({
            ...p,
            communityId: p.communityId || p.community || p.site || undefined,
            communityLabel: p.communityLabel || p.community || p.site || undefined,
          })) as Post[];
          loadedGenerationRef.current = generation ?? loadedGenerationRef.current;
          // Write-through to cache (best-effort)
          try {
            const ver = generation;
            if (ver) await cacheWritePage(base, pageNum, ver, incoming as unknown as ClientPost[]);
          } catch { /* ignore */ }
          if (!isCurrent()) return { status: 'error', newPosts: [] };
          // Prefetch next page in background
          try {
            const next = pageNum + 1;
            const key = `${base}|${next}`;
            if ((manifest?.lastPage === undefined || next <= manifest.lastPage) && !prefetchingRef.current.has(key)) {
              prefetchingRef.current.add(key);
              (async () => {
                try {
                  const r = await fetch(`${base}/page-${next}.json`, { cache: 'no-store' });
                  if (r.ok) {
                    const d = await r.json();
                    if (generation && (manifest.seedPolicy === 'live-seed-dedupe' || typeof d.generatedAt === 'string') && d.generatedAt !== generation) return;
                    const arr = (Array.isArray(d.posts) ? d.posts : []) as Post[];
                    const norm = arr.map((p: Post & { community?: string; site?: string }) => ({
                      ...p,
                      communityId: p.communityId || p.community || p.site || undefined,
                      communityLabel: p.communityLabel || p.community || p.site || undefined,
                    })) as Post[];
                    const ver2 = generation;
                    if (ver2) await cacheWritePage(base, next, ver2, norm as unknown as ClientPost[]);
                  }
                } catch { /* ignore */ }
                finally { prefetchingRef.current.delete(key); }
              })();
            }
          } catch { /* ignore */ }
          const sampleIds = incoming.slice(0, 5).map((p) => p.id);
          dlog("loadPage:ok", { pageNum, incomingCount: incoming.length, sampleIds });
          const uniques = incoming.filter((p) => !seenIdsRef.current.has(p.id) && !excludedIdsRef.current.has(p.id));
          dlog("loadPage:dedup", {
            pageNum,
            uniquesCount: uniques.length,
            status: uniques.length > 0 ? "ok-new" : "ok-dup",
          });
          return {
            status: uniques.length > 0 ? "ok-new" : "ok-dup",
            newPosts: uniques,
          };
        } catch (e: unknown) {
          const message = e instanceof Error ? e.message : String(e);
          dlog("loadPage:error", { pageNum, attempt: i, message, aborted: signal?.aborted });
          if (!isCurrent()) {
            return { status: "error", newPosts: [] };
          }
          if (i === RETRY_BACKOFFS.length) {
            recentFailRef.current.set(pageNum, Date.now());
            return { status: "error", newPosts: [] };
          }
          dlog("loadPage:retrying", { pageNum, backoffMs: RETRY_BACKOFFS[i] });
          await new Promise((r) => setTimeout(r, RETRY_BACKOFFS[i]));
        }
      }
      return { status: "error", newPosts: [] };
    },
    [jsonBase, maybeRefreshManifest, sectionKey, stopForNewGeneration]
  );

  const loadMore = useCallback(async () => {
    // A caller may retain an exported navigation API after the section changes.
    // Reject it before it can abort or lock the new section's active request.
    if (prevSectionKeyRef.current !== sectionKey) return;
    if (isFetchingRef.current || !hasMoreRef.current) return;
    const epoch = sectionEpochRef.current;
    const ac = new AbortController();
    currentAbortRef.current?.abort();
    currentAbortRef.current = ac;
    const myToken = ++fetchTokenRef.current;
    const isCurrent = () => fetchTokenRef.current === myToken && sectionEpochRef.current === epoch && prevSectionKeyRef.current === sectionKey;
    isFetchingRef.current = true;
    setIsFetching(true);
