      openModal(post.id, postIds);
    };

    return (
      <>
        <Show when="signed-in">
          <Link
            id={`post-${post.id}`}
            href={`/posts/${post.id}`}
            prefetch={!isMobile}
            className={cn(`block ${isNew ? 'fade-in' : ''}`, isRead && 'is-read')}
            data-read={isRead ? '1' : undefined}
            onClick={handleClick}
          >
            <Card className="transition-shadow cursor-pointer hover:shadow-md">
              <SignedInCardContent />
            </Card>
          </Link>
        </Show>
        <Show when="signed-out">
          <a
            id={`post-${post.id}`}
            href={post.url}
            target="_blank"
            rel="noopener noreferrer"
            className={cn(`block ${isNew ? 'fade-in' : ''}`, isRead && 'is-read')}
            data-read={isRead ? '1' : undefined}
            onClick={() => markPostAsRead({ id: post.id, title: post.title, url: post.url })}
          >
            <Card className="transition-shadow cursor-pointer hover:shadow-md">
              <SignedOutCardContent />
            </Card>
          </a>
        </Show>
      </>
    );
  });

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { BrandIcon } from "@/components/brand-icon";
import { prepareReturnFromDetail } from "@/lib/restore-session";
import {
  ThumbsUp,
  MessageCircle,
  Eye,
  Share2,
  Bookmark,
  ArrowLeft,
  Flag,
} from "lucide-react";
import Link from "next/link";

import type { getPostDetail } from "@/lib/queries";
import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import { useKeywordManifest } from "@/hooks/use-keyword-manifest";

interface PostDetailProps {
  post: Awaited<ReturnType<typeof getPostDetail>> extends infer T
  ? NonNullable<T>
  : never;
  inDialog?: boolean;
}

const communityColors: Record<string, string> = {
  FMKorea: "bg-blue-100 text-blue-800",
  Clien: "bg-green-100 text-green-800",
  Inven: "bg-purple-100 text-purple-800",
  MLBPARK: "bg-orange-100 text-orange-800",
  디시인사이드: "bg-red-100 text-red-800",
  루리웹: "bg-yellow-100 text-yellow-800",
  보배드림: "bg-indigo-100 text-indigo-800",
};

export function PostDetail({ post, inDialog }: PostDetailProps) {
  const [upvoted, setUpvoted] = useState(false);
  const [bookmarked, setBookmarked] = useState(false);
  const [copied, setCopied] = useState(false);
  const router = useRouter();
  const contentRef = useRef<HTMLDivElement | null>(null);
  const { getKeywordLink } = useKeywordManifest();

  const copyShareLink = async () => {
    const shareUrl = `${window.location.origin}/posts/${post.id}`;
    try {
      if (navigator?.clipboard?.writeText) {
        await navigator.clipboard.writeText(shareUrl);
      } else {
        const ta = document.createElement("textarea");
        ta.value = shareUrl;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
      }
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch (e) {
      console.error("Failed to copy share link", e);
    }
  };


  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("ko-KR", {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const handleUpvote = () => {
    setUpvoted(!upvoted);
  };

  // Normalize enrichment arrays
  const categories = Array.isArray(post.categories) ? post.categories : [];
  const tags = Array.isArray(post.keywords) ? post.keywords : [];
  const hasYouTube = post.embeds.some((e) => e.type === 'youtube');
  const hasX = post.embeds.some((e) => e.type === 'X');

  // Enhance media UX inside crawled HTML (open large images in new tab)
  useEffect(() => {
    const el = contentRef.current;
    if (!el) return;
    const handler = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;
      // If user clicks an image without a link, open original in new tab
      if (target.tagName === 'IMG') {
        const img = target as HTMLImageElement;
        const parentLink = img.closest('a');
        if (!parentLink && img.src) {
          window.open(img.src, '_blank', 'noopener,noreferrer');
        }
      }
    };
    el.addEventListener('click', handler);
    return () => el.removeEventListener('click', handler);
  }, [post.id]);

  // When landing on the full page with ?goto=comments or #comments, jump to the comments section
  useEffect(() => {
    if (inDialog) return;
    try {
      const params = new URLSearchParams(window.location.search);
      const wantsComments = params.get("goto") === "comments" || window.location.hash === "#comments";
      if (!wantsComments) return;
      const el = document.getElementById("comments");
      if (el) el.scrollIntoView({ behavior: "auto", block: "start" });
    } catch { /* no-op */ }
  }, [inDialog]);

  // Effect to handle cross-origin videos via client-side fetch and blob URL
  useEffect(() => {
    const contentEl = contentRef.current;
    if (!contentEl) return;

    const videos = contentEl.querySelectorAll('video');

    videos.forEach(async (video) => {
      let originalSrc = video.src;
      if (!originalSrc) {
        const source = video.querySelector('source');
        if (source) {
          originalSrc = source.src;
        }
      }

      if (originalSrc && (originalSrc.startsWith('http:') || originalSrc.startsWith('https:'))) {
        // Avoid re-fetching blob URLs
        if (originalSrc.startsWith('blob:')) {
          return;
        }

        // Set a loading state
        video.style.opacity = '0.5';
        const poster = video.poster;
        video.poster = ''; // Clear poster to show loading state if any

        try {
          const response = await fetch(originalSrc, { referrerPolicy: 'no-referrer' });

          if (!response.ok) {
            throw new Error(`Failed to fetch video: ${response.status} ${response.statusText}`);
          }

          const videoBlob = await response.blob();
          const blobUrl = URL.createObjectURL(videoBlob);

          video.src = blobUrl;
          video.style.opacity = '1';
          video.poster = poster; // Restore original poster
        } catch (error) {
          console.error(`[Video Fetch Error] Could not load video from ${originalSrc}. This is likely a CORS issue.`, error);
          // Indicate the error on the video element itself
          video.style.opacity = '0.2';
          video.poster = 'data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0iI2ZmZmZmZiI+PHBhdGggZD0iTTEyIDJDNi40OCA MiAyIDYuNDggMiAxMnM0LjQ4IDEwIDEwIDEwIDEwLTQuNDggMTAtMTBTMTcuNTIgMiAxMiAyem0wIDE4Yy00LjQxIDAtOC0zLjU5LTgtOHMzLjU5LTggOC04IDggMy41OSA4IDh6TTExIDE1aDJ2MmgxMXYtMnpNMT EgN2gydjZoLTF6Ii8+PC9zdmc+'; // Simple error icon
        }
      }
    });
  }, [post.id]);

  useEffect(() => {
    const el = contentRef.current;
    const enrichments = Array.isArray(post.imageEnrichments) ? post.imageEnrichments : [];
    if (!el || enrichments.length === 0) return;

    const normalizeUrl = (raw: string) => {
      if (!raw) return '';
      try {
        const url = new URL(raw, typeof window !== 'undefined' ? window.location.href : 'https://example.invalid');
        if (url.protocol === 'http:') url.protocol = 'https:';
        return url.href;
      } catch {
        return raw;
      }
    };

    const enrichmentMap = new Map<string, (typeof enrichments)[number]>();
    for (const item of enrichments) {
      if (!item?.imageUrl) continue;
      const full = normalizeUrl(item.imageUrl);
      const noHash = full.split('#')[0] ?? full;
      const noQuery = noHash.split('?')[0] ?? noHash;
      for (const key of [full, noHash, noQuery]) {
        if (key && !enrichmentMap.has(key)) enrichmentMap.set(key, item);
      }
    }

    const ensureFigure = (img: HTMLImageElement) => {
      const existing = img.closest('figure');
      if (existing) {
        existing.classList.add('reader-ai-figure');
        return existing as HTMLElement;
      }

      const wrapper = document.createElement('figure');
      wrapper.classList.add('reader-ai-figure');
      wrapper.dataset.aiWrapper = '1';

      const anchor = img.closest('a');
      const parent = anchor?.parentElement ?? img.parentElement;
      if (!parent) return null;

      if (anchor && anchor.contains(img) && anchor.querySelectorAll('img').length === 1 && anchor.textContent?.trim() === '') {
        parent.insertBefore(wrapper, anchor);
        wrapper.appendChild(anchor);
      } else {
        parent.insertBefore(wrapper, img);
        wrapper.appendChild(img);
      }

      return wrapper;
    };

    const buildCaption = (item: (typeof enrichments)[number]) => {
      const caption = document.createElement('figcaption');
      caption.classList.add('ai-figcaption');

      const titleRow = document.createElement('div');
      titleRow.classList.add('ai-figcaption-title');
      titleRow.textContent = 'AI 이미지 설명';
      caption.appendChild(titleRow);

      const captionText = document.createElement('p');
      captionText.classList.add('ai-figcaption-text');
      captionText.textContent = item.caption?.trim() || '설명을 가져오지 못했습니다.';
      caption.appendChild(captionText);

      const detailsContent: HTMLElement[] = [];

      if (Array.isArray(item.labels) && item.labels.length > 0) {
        const dd = document.createElement('dd');
        dd.textContent = item.labels.map((label: unknown) => String(label)).join(', ');
        const dt = document.createElement('dt');
        dt.textContent = '키워드';
        detailsContent.push(dt, dd);
      }

      if (Array.isArray(item.ocrLines)) {
        const lines = item.ocrLines.map((line: unknown) => String(line).trim()).filter(Boolean);
        if (lines.length > 0) {
          const dt = document.createElement('dt');
          dt.textContent = 'OCR';
          const dd = document.createElement('dd');
          lines.forEach((line, idx) => {
            const span = document.createElement('span');
            span.textContent = line;
            dd.appendChild(span);
            if (idx < lines.length - 1) dd.appendChild(document.createElement('br'));
          });
          detailsContent.push(dt, dd);
        }
      }

      if (Array.isArray(item.objects) && item.objects.length > 0) {
        const formatted = item.objects.map((obj: { name?: string; count?: number; confidence?: number }) => {
          const parts = [String(obj?.name ?? '')];
          if (typeof obj?.count === 'number' && obj.count > 0) parts.push(`x${obj.count}`);
          if (typeof obj?.confidence === 'number') parts.push(`${Math.round(obj.confidence * 100)}%`);
          return parts.filter(Boolean).join(' ');
        }).filter(Boolean);
        if (formatted.length > 0) {
          const dt = document.createElement('dt');
          dt.textContent = '감지 객체';
          const dd = document.createElement('dd');
          dd.textContent = formatted.join(', ');
          detailsContent.push(dt, dd);
        }
      }

      if (item.safety && typeof item.safety === 'object') {
        const safetyEntries = Object.entries(item.safety as Record<string, unknown>)
          .filter(([, value]) => typeof value === 'number');
        if (safetyEntries.length > 0) {
          const dt = document.createElement('dt');
          dt.textContent = '안전성';
          const dd = document.createElement('dd');
          dd.textContent = safetyEntries
            .map(([key, value]) => `${key}: ${(value as number).toFixed(2)}`)
            .join(', ');
          detailsContent.push(dt, dd);
        }
      }

      if (item.model) {
        const dt = document.createElement('dt');
        dt.textContent = '모델';
        const dd = document.createElement('dd');
        dd.textContent = String(item.model);
        detailsContent.push(dt, dd);
      }

      if (item.enrichedAt) {
        try {
          const dt = document.createElement('dt');
          dt.textContent = '생성 시간';
          const dd = document.createElement('dd');
          const date = new Date(String(item.enrichedAt));
          dd.textContent = Number.isNaN(date.valueOf())
            ? String(item.enrichedAt)
            : date.toLocaleString('ko-KR', { dateStyle: 'medium', timeStyle: 'short' });
          detailsContent.push(dt, dd);
        } catch {
          /* ignore date parse errors */
        }
      }

      if (detailsContent.length > 0) {
        const details = document.createElement('details');
        details.classList.add('ai-figcaption-details');
        const summary = document.createElement('summary');
        summary.textContent = '추가 정보 보기';
        details.appendChild(summary);

        const dl = document.createElement('dl');
        dl.classList.add('ai-figcaption-meta');
        detailsContent.forEach((node) => dl.appendChild(node));
        details.appendChild(dl);
        caption.appendChild(details);
      }

      return caption;
    };

    const applyCaptions = () => {
      const images = Array.from(el.querySelectorAll<HTMLImageElement>('img'));
      images.forEach((img) => {
        const srcAttr = img.getAttribute('src') || img.currentSrc || img.src;
        if (!srcAttr) return;
        const normalizedSrc = normalizeUrl(srcAttr);
        const lookupKeys = [
          normalizedSrc,
          normalizedSrc.split('#')[0] ?? normalizedSrc,
          normalizedSrc.split('?')[0] ?? normalizedSrc,
        ];

        let data: (typeof enrichments)[number] | undefined;
        for (const key of lookupKeys) {
          if (!key) continue;
          data = enrichmentMap.get(key);
          if (data) break;
        }

        if (!data) return;

        const figure = ensureFigure(img);
        if (!figure) return;

        const signature = JSON.stringify({
          caption: data.caption ?? '',
          labels: Array.isArray(data.labels) ? data.labels : [],
          ocr: Array.isArray(data.ocrLines) ? data.ocrLines : [],
          model: data.model ?? '',
          safety: data.safety ?? null,
          enrichedAt: data.enrichedAt ?? '',
        });

        if (figure.dataset.aiCaptionKey === signature && figure.querySelector('.ai-figcaption')) {
          return;
        }

        figure.querySelectorAll('.ai-figcaption').forEach((node) => node.remove());
        const caption = buildCaption(data);
        figure.appendChild(caption);
        figure.dataset.aiCaptionKey = signature;
      });
    };

    // Initial pass once content is ready
    applyCaptions();

    // Observe future changes (lazy image loading, ads stripped, etc.)
    const observer = new MutationObserver(() => {
      // Run in next frame to batch rapid mutations
      requestAnimationFrame(applyCaptions);
    });
    observer.observe(el, { childList: true, subtree: true });

    return () => {
      observer.disconnect();
    };
  }, [post.id, post.imageEnrichments, post.imageEnrichmentUpdatedAt]);

  // Note: previous dev-only overflow logger and runtime image normalization were removed
  // to reduce complexity. Server-side HTML normalization + CSS handle layout now.

  return (
    <div className="space-y-6">
      {/* Back Button */}
      {inDialog ? (
        <Button
          variant="ghost"
          size="sm"
          className="mb-4"
          onClick={() => {
            // In a modal (intercepted route), simply close by navigating back
            router.back();
          }}
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          목록으로 돌아가기
        </Button>
      ) : (
        <Button
          variant="ghost"
          size="sm"
          className="mb-4"
          onClick={() => {
            try {
              const key = sessionStorage.getItem("lastSectionKey/latest") || "";
              if (key) {
                prepareReturnFromDetail(key, post.id);
                const src = sessionStorage.getItem(`sourceUrl-${key}/latest`);
                if (src) {
                  router.replace(src);
                  return;
                }
              }
              router.replace("/");
            } catch {
              router.replace("/");
            }
          }}
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          목록으로 돌아가기
        </Button>
      )}

      {/* Post Header */}
      <Card>
        <CardHeader className="space-y-4">
          <div className="flex items-center justify-between">
            <Badge
              variant="secondary"
              className={
                communityColors[post.siteName || post.site] || "bg-gray-100 text-gray-800"}
            >
              {post.siteName || post.site}            </Badge>
            <div className="flex items-center gap-2 text-sm text-gray-500">
              {hasYouTube && <BrandIcon name="youtube" useBrandColor className="h-3.5 w-3.5" />}
              {hasX && <BrandIcon name="X" useBrandColor className="h-3.5 w-3.5" />}
              <Eye className="h-4 w-4" />
              <span>{post.viewCount?.toLocaleString?.() ?? 0}</span>
            </div>
          </div>

          <h1 className="text-2xl md:text-3xl font-bold text-gray-900 leading-tight">
            {inDialog ? (
              <Link
                href={`/posts/${post.id}`}
                className="transition-colors hover:text-gray-400 hover:underline"
              >
                {post.title}
              </Link>
            ) : (
              post.title
            )}
          </h1>

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Avatar className="h-8 w-8">
                {post.avatar ? (
                  <AvatarImage src={post.avatar} alt={post.author ?? "Avatar"} />
                ) : (
                  <AvatarFallback>{post.author?.[0] ?? "?"}</AvatarFallback>
                )}
              </Avatar>
              <div>
                <div className="font-medium text-sm">
                  {post.author ?? "익명"}
                </div>
                <div className="text-xs text-gray-500">
                  {formatDate(post.timestamp)}
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setBookmarked(!bookmarked)}
              >
                <Bookmark
                  className={`h-4 w-4 ${bookmarked ? "fill-current" : ""}`}
                />
              </Button>
              <Button variant="ghost" size="sm" onClick={copyShareLink} title="링크 복사">                <Share2 className="h-4 w-4" />
              </Button>
              <Button variant="ghost" size="sm">
                <Flag className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* 원본 링크 */}
          {post.url && (
            <div className="mt-2">
              <a
                href={post.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-xs text-blue-600 underline hover:text-blue-800"
              >
                원본 게시글 보기 ↗
              </a>
            </div>
          )}

          {/* Categories & Tags (LLM Enrichment) */}
          {(categories.length > 0 || tags.length > 0) && (
            <div className="mt-2 space-y-2">
              {categories.length > 0 && (
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-xs text-gray-500">카테고리</span>
                  {categories.map((c: string | number, idx: number) => (
                    <Badge key={`cat-${idx}`} variant="secondary">
                      {String(c)}
                    </Badge>
                  ))}
                </div>
              )}
              {tags.length > 0 && (
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-xs text-gray-500">태그</span>
                  {tags.map((t: string | number, idx: number) => (
                    <Link key={`tag-${idx}`} href={getKeywordLink(String(t))} passHref>
                      <span
                        className="inline-flex items-center rounded-full border px-2 py-0.5 text-xs text-gray-700 bg-gray-50 hover:bg-gray-100 hover:text-gray-900 cursor-pointer"
                      >
                        #{String(t)}
                      </span>
                    </Link>
                  ))}
                </div>
              )}
            </div>
          )}
        </CardHeader>
      </Card>

      {/* Post Content */}
      <Card>
        <CardContent className="p-6">
          <div
            ref={contentRef}
            className={cn(
              "reader",
              inDialog && "reader--dialog"
            )}
            dangerouslySetInnerHTML={{ __html: post.contentHtml || "" }}
          />
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <Card>
        <CardContent className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Button
                variant={upvoted ? "default" : "outline"}
                size="sm"
                onClick={handleUpvote}
                className="flex items-center gap-2"
              >
                <ThumbsUp className="h-4 w-4" />
                <span>{(post.likeCount ?? 0) + (upvoted ? 1 : 0)}</span>
              </Button>

              <Button
                variant="outline"
                size="sm"
                className="flex items-center gap-2"
                onClick={() => {
                  console.log("Comment button clicked");
                  console.log("inDialog:", inDialog);
                  if (inDialog) {
                    const url = `/posts/${post.id}?goto=comments`;
                    console.log("Navigating to:", url);
                    try {
                      // 모달(가로채기) 히스토리 항목을 전체 페이지로 교체하여 히스토리 오염 방지
                      window.location.replace(url);
                    } catch (e) {
                      console.error("Error during location.replace:", e);
                      window.location.href = url;
                    }
                  } else {
                    // On the real page, to comments if present
                    console.log("Scrolling to #comments");
                    const el = document.getElementById("comments");
                    if (el) el.scrollIntoView({ behavior: "auto", block: "start" });
                  }
                }}
              >
                <MessageCircle className="h-4 w-4" />
                <span>댓글 {post.commentCount ?? 0}</span>
              </Button>
            </div>

            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={copyShareLink} title="링크 복사">
                {copied ? "복사됨!" : "공유하기"}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import InfinitePostList from "@/components/infinite-post-list";
import { Info } from "lucide-react";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import ClientRandomClamp from "@/components/client-random-clamp";
import { PostListProvider } from "@/context/post-list-context";
import type { Range, Post } from "@/lib/types";

interface PostGridProps {
  title: string;
  range?: Range; // 시간 필터
  perSiteCap?: number;                // 사이트 캡
  layout?: "list" | "grid";
  mode?: "ranked" | "fresh";          // 선정 기준
  /**
   * 서버 상위 컴포넌트에서 미리 선별/중복제거한 포스트가 있다면 주입.
   * 주입되면 내부에서 쿼리를 호출하지 않고 해당 데이터로 그대로 그립니다.
   * (섹션 간 중복 제거 및 차별화 목적)
   */
  initialPosts?: Post[];
  initialSampledPosts?: Post[];
  clampSeed?: number;
  jsonBase?: string;
  enablePaging?: boolean;
  community?: string;
  category?: string;
  sampleMax?: number;
  rows?: number;
  randomizeOnEachMount?: boolean;
  refreshToken?: string | number;
  // Virtualized list customizations for category pages
  listColumns?: 'auto-2' | '3-2-1';
  cardLayoutOverride?: 'grid' | 'list';
  threeColAt?: 'lg' | 'xl';
  readFilter?: string;
  excludedPostIds?: string[];
}

export default function PostGrid({
  title,
  range = "24h",
  perSiteCap = 6,
  layout = "grid",
  mode = "ranked",
  initialPosts,
  initialSampledPosts,
  clampSeed,
  jsonBase,
  enablePaging = true,
  community,
  category,
  sampleMax,
  rows,
  randomizeOnEachMount,
  refreshToken,
  listColumns,
  cardLayoutOverride,
  threeColAt,
  readFilter,
  excludedPostIds,
}: PostGridProps) {
  // For the "최신" section, enforce fresh mode; for both "최신" and "지금 주목" display range in the title.
  const isLatestTimeline = title.includes("최신");
  const isSpotlight = title.includes("지금 주목");
  const effectiveMode: "ranked" | "fresh" = isLatestTimeline ? "fresh" : mode;
  const selectedRange: Range = range;
  const effectiveRange: Range = selectedRange;
  const RANGE_LABEL: Record<Range, string> = { "3h": "3시간", "6h": "6시간", "24h": "24시간", "1w": "1주일" } as const;
  const rangeLabel = RANGE_LABEL[effectiveRange];
  const displayTitle = isLatestTimeline
    ? `최신 (${rangeLabel})`
    : isSpotlight
      ? `지금 주목 (${rangeLabel} 랭킹)`
      : title;
  const posts = initialPosts ?? [];

  const mapped = posts; // Data from hydratePosts is already in the correct shape for PostCard

  const defaultSection = effectiveMode === "fresh" ? "fresh" : "ranked";
  // If a category is provided, page JSONs live under /data/category/<category>/v1
  const base = enablePaging
    ? (jsonBase ?? (category ? `/data/category/${category}/v1` : `/data/home/v1/${effectiveRange}/${defaultSection}`))
    : undefined;
  // Make restoration keys distinct per section/mode/range to avoid bleed across range changes
  const storageKey = `${title} [${defaultSection}|${effectiveRange}]`;
  console.log(`11111 [${defaultSection}|${effectiveRange}] ${title}`)
  return (
    <div className="space-y-4">
      {displayTitle && <h2 className="text-xl font-semibold text-gray-900">{displayTitle}</h2>}
      <div className="flex items-center gap-2 text-xs text-gray-500">
        <span>
          {title.includes("급상승") && "최근 3시간 내 반응 급증 글을 균형 있게 보여줘요."}
          {title.includes("지금 주목") && `${rangeLabel} 범위에서 주목받는 글을 랭킹으로 보여줘요.`}
          {title.includes("오늘의 이슈") && "최근 24시간 이슈를 묶음(클러스터)으로 대표 글만 보여줘요."}
          {title.includes("이번주") && "최근 1주 이슈를 묶음(클러스터)으로 대표 글만 보여줘요."}
          {title.includes("최신") && `선택한 시간 범위(${rangeLabel}) 내에서 활동도 기반 점수로 정렬된 최신 글이에요. 아래로 더 내리면 계속 이어집니다.`}
        </span>
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <button aria-label="설명" className="inline-flex items-center text-gray-400 hover:text-gray-600">
                <Info className="h-3.5 w-3.5" />
              </button>
            </TooltipTrigger>
            <TooltipContent side="top">
              <p>
                {title.includes("급상승") && "3시간 기준, 사이트 편중을 줄이고 최근성 가중치로 선별합니다."}
                {title.includes("지금 주목") && `${rangeLabel} 범위에 따라 랭킹이 동적으로 바뀝니다.`}
                {title.includes("오늘의 이슈") && "유사 이슈는 하나로 묶어 대표 글만 노출합니다."}
                {title.includes("이번주") && "1주 기준 이슈 묶음의 대표 글을 보여줍니다."}
                {title.includes("최신") && `무한 스크롤은 현재 선택한 범위(${rangeLabel})의 ‘최신’ 피드를 이어붙입니다. (시간순 정렬이 아닌 활동도 가중 점수 정렬)`}
              </p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      </div>
      {/* 샘플링 조건: 페이징 비활성 + sampleMax 지정됨 */}
      {(!enablePaging && !!sampleMax) ? (
        <ClientRandomClamp
          key={refreshToken != null ? `${title}-${refreshToken}` : undefined}
          items={mapped}
          sampleMax={sampleMax}
          layout={layout}
          community={community}
          jsonBase={base}
          storageKeyPrefix={storageKey}
          rows={rows}
          randomizeOnEachMount={!!randomizeOnEachMount}
          initialSampled={initialSampledPosts}
          initialSeed={clampSeed}
        />
      ) : (
        <PostListProvider postIds={mapped.map(p => p.id)}>
          <InfinitePostList
            initialPosts={mapped}
            community={community}
            layout={layout}
            jsonBase={base}
            enablePaging={enablePaging}
            storageKeyPrefix={storageKey}
            listColumns={listColumns}
            cardLayoutOverride={cardLayoutOverride}
            threeColAt={threeColAt}
            readFilter={readFilter}
            excludedPostIds={excludedPostIds}
          />
        </PostListProvider>
      )}
    </div>
  );
}

import Image from 'next/image';
import * as React from 'react';
import type { Post } from '@/lib/types';

// Local Post interface removed - using imported type from lib/types

interface PostHoverCardProps {
  post: Post;
}

function toYouTubeEmbed(url: string): string {
  try {
    // Accept watch URLs, share URLs, or already-embed URLs
    const u = new URL(url);
    if (u.hostname.includes('youtube.com')) {
      // watch?v=VIDEOID or embed/VIDEOID
      if (u.pathname.startsWith('/embed/')) return url;
      const id = u.searchParams.get('v');
      return id ? `https://www.youtube.com/embed/${id}` : url;
    }
    if (u.hostname === 'youtu.be') {
      const id = u.pathname.replace('/', '');
      return id ? `https://www.youtube.com/embed/${id}` : url;
    }
    return url;
  } catch {
    return url;
  }
}

function extractTweetId(raw: string): string | null {
  try {
    const u = new URL(raw.replace('://x.com', '://twitter.com'));
    const seg = u.pathname.split('/').filter(Boolean);

    // /{user}/status/{id}
    if (seg.length >= 3 && seg[1] === 'status') return seg[2];

    // /i/status/{id} 또는 /i/web/status/{id}
    if (seg[0] === 'i' && (seg[1] === 'status' || (seg[1] === 'web' && seg[2] === 'status'))) {
      return seg[seg.length - 1];
    }
    return null;
  } catch {
    return null;
  }
}

function toXEmbed(url: string): string {
  const id = extractTweetId(url);
  if (id) {
    // ✅ 공식 임베드 iframe
    return `https://platform.twitter.com/embed/Tweet.html?id=${encodeURIComponent(id)}`;
  }
  // id를 못 캐면 차선: publish.twitter.com로 변환해서 얻은 embed 코드(서버측 oEmbed) 사용 고려
  return `https://platform.twitter.com/embed/Tweet.html`; // 최소한 실패 시 빈 프레임 방지
}

import { cn } from "@/lib/utils";

export function PostHoverCard({ post }: PostHoverCardProps) {
  const kind = post.hoverPlayerKind ?? null;
  const src = post.hoverPlayerUrl ?? null;
  // Clean up text: collapse nbsp/multiple spaces and excessive newlines, trim trailing blank lines
  const text = React.useMemo(() => {
    const raw = (post.content || '').replace(/\u00a0/g, ' ');
    const collapsedSpaces = raw.replace(/[\t ]+/g, ' ');
    const collapsedNewlines = collapsedSpaces.replace(/\n{2,}/g, '\n');
    return collapsedNewlines.replace(/\n+$/g, '').trim();
  }, [post.content]);
  const nl = (text.match(/\n/g) || []).length;
  const isLong = text.length > 120 || nl >= 2;
  const isShort = text.length <= 60 && nl === 0;
  // Hover media sizing now controlled by HoverCardContent width.
  // Keep inner containers full-width of the hover card.
  const [thumbOk, setThumbOk] = React.useState(true);

  if (kind === 'youtube' && src) {
    const embed = toYouTubeEmbed(src);
    return (
      <div className="p-4 space-y-3">
        <div className={cn("w-full rounded-lg overflow-hidden mx-auto") }>
          <div className="relative w-full aspect-video">
            <iframe
              className="absolute inset-0 w-full h-full"
              src={embed}
              title={post.title}
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            />
          </div>
        </div>
        <div className={cn("mx-auto max-w-[62ch] max-h-40 overflow-y-auto text-[0.95rem] leading-6 text-gray-800 whitespace-pre-line", isLong && 'pr-1')}>{text}</div>
      </div>
    );
  }

  if (kind === 'x' && src) {
    const embed = toXEmbed(src);
    return (
      <div className="p-4 space-y-3">
        <div className={cn("w-full rounded-lg overflow-hidden mx-auto") }>
          <iframe
            className={cn("w-full", isLong ? 'h-[360px]' : 'h-[420px]')}
            src={embed}
            title={post.title}
            allow="autoplay; clipboard-write; encrypted-media; picture-in-picture"
          />
        </div>
        <div className={cn("mx-auto max-w-[62ch] max-h-40 overflow-y-auto text-[0.95rem] leading-6 text-gray-800 whitespace-pre-line", isLong && 'pr-1')}>{text}</div>
      </div>
    );
  }

  if (kind === 'mp4' && src) {
    return (
      <div className="p-4 space-y-3">
        <div className={cn("relative w-full rounded-lg overflow-hidden mx-auto") }>
          <video
            src={src}
            autoPlay
            muted
            loop
            playsInline
            controls
            className="w-full h-auto"
            style={{ maxHeight: isLong ? '50vh' : '60vh' }}
          />
        </div>
        <div className={cn("mx-auto max-w-[62ch] max-h-40 overflow-y-auto text-[0.95rem] leading-6 text-gray-800 whitespace-pre-line", isLong && 'pr-1')}>{text}</div>
      </div>
    );
  }

  return (
    <div className="p-4 space-y-3">
      {post.thumbnail && thumbOk && (
        <div className={cn("rounded-lg overflow-y-auto mx-auto w-full")} style={{ maxHeight: '60vh' }}>
          <Image
            src={post.thumbnail}
            alt={post.title}
            width={720}
            height={405}
            className="w-full h-auto"
            sizes="(max-width: 1024px) 90vw, 720px"
            onError={() => setThumbOk(false)}
          />
        </div>
      )}
      <div className={cn("mx-auto max-w-[62ch] max-h-40 overflow-y-auto text-[0.95rem] leading-6 text-gray-800 whitespace-pre-line", isLong && 'pr-1')}>{text}</div>
    </div>
  );
}

