'use client';

import { useEffect, useState, useRef } from 'react';
import { useModal } from '@/context/modal-context';
import type { Post } from '@/lib/types';
import { PostDetail } from '@/components/post-detail';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Skeleton } from '@/components/ui/skeleton';
import { ScrollProgress } from '@/components/animate-ui/components/scroll-progress';

// Helper to check if the user is typing in an input
const isTyping = (el: Element | null) => {
  if (!el || !(el instanceof HTMLElement)) return false;
  const tag = el.tagName.toLowerCase();
  return tag === 'input' || tag === 'textarea' || el.isContentEditable;
};


// Helper function to fetch a single post from the static JSON files
async function getStaticPost(id: string): Promise<Post | null> {
  try {
    const res = await fetch(`/data/posts/v1/${id}.json`);
    if (!res.ok) {
      console.error(`Failed to fetch post data for id: ${id}`);
      return null;
    }
    const data = await res.json();
    return data as Post;
  } catch (error) {
    console.error(error);
    return null;
  }
}

// Skeleton loader for the post detail view
function PostDetailSkeleton() {
  return (
    <div className="p-6">
      <Skeleton className="h-8 w-2/3 mb-4" />
      <div className="space-y-2">
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-4/5" />
      </div>
    </div>
  );
}

export function PostViewerModal() {
  const { isOpen, closeModal, postId, navigateToPost } = useModal();
  const [post, setPost] = useState<Post | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const contentRef = useRef<HTMLDivElement | null>(null);

  // Data fetching effect
  useEffect(() => {
    if (postId) {
      setIsLoading(true);
      setPost(null);
      getStaticPost(postId)
        .then(data => {
          setPost(data);
        })
        .finally(() => {
          setIsLoading(false);
        });
    } else {
      setPost(null);
    }
  }, [postId]);

  // Scroll to top when post changes
  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [postId]);

  // Help overlay effect
  useEffect(() => {
    if (isOpen) {
      setShowHelp(true);
      const timer = setTimeout(() => setShowHelp(false), 6000);
      const hide = () => setShowHelp(false);
      window.addEventListener("keydown", hide, { once: true });
      return () => {
        clearTimeout(timer);
        window.removeEventListener("keydown", hide);
      };
    }
  }, [isOpen]);

  // Keyboard shortcuts effect
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isTyping(document.activeElement)) return;

      // Navigation
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        navigateToPost('prev');
        return;
      }
      if (e.key === 'ArrowRight') {
        e.preventDefault();
        navigateToPost('next');
        return;
      }

      const scrollEl = contentRef.current;
      if (!scrollEl) return;

      const handleScroll = (amount: number) => {
        scrollEl.scrollBy({ top: amount, behavior: 'smooth' });
      };

      // Scrolling
      switch (e.code) {
        case "KeyJ":
        case "ArrowDown":
          e.preventDefault();
          handleScroll(80);
          return;
        case "KeyK":
        case "ArrowUp":
          e.preventDefault();
          handleScroll(-80);
          return;
        case "PageDown":
        case "Space":
          e.preventDefault();
          if (e.code === "Space" && scrollEl.scrollTop + scrollEl.clientHeight >= scrollEl.scrollHeight - 2) {
            navigateToPost('next');
          } else {
            handleScroll(scrollEl.clientHeight);
          }
          return;
        case "PageUp":
          e.preventDefault();
          handleScroll(-scrollEl.clientHeight);
          return;
        case "Home":
          e.preventDefault();
          scrollEl.scrollTo({ top: 0, behavior: 'smooth' });
          return;
        case "End":
          e.preventDefault();
          scrollEl.scrollTo({ top: scrollEl.scrollHeight, behavior: 'smooth' });
          return;
      }
    };

    if (isOpen) {
      window.addEventListener('keydown', handleKeyDown);
    }
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, navigateToPost]);

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      closeModal();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent
        className="w-screen max-w-screen sm:w-screen sm:max-w-screen md:max-w-4xl h-[90dvh] md:h-5/6 p-0 flex flex-col rounded-none sm:rounded-none md:rounded-lg top-0 left-0 translate-x-0 translate-y-0 md:left-1/2 md:top-1/2 md:-translate-x-1/2 md:-translate-y-1/2"
      >
        <DialogHeader className="sr-only">
          <DialogTitle>{post?.title || "Loading..."}</DialogTitle>
          <DialogDescription>Post content</DialogDescription>
        </DialogHeader>

        <ScrollProgress ref={contentRef} className="flex-1 p-0">
          {isLoading && <PostDetailSkeleton />}
          {!isLoading && post && <PostDetail post={post as unknown as Parameters<typeof PostDetail>[0]['post']} inDialog={true} />}
          {!isLoading && postId && !post && (
            <div className="p-6 text-center">Post not found or failed to load.</div>
          )}
        </ScrollProgress>

        {showHelp && (
          <div className="pointer-events-auto fixed bottom-4 left-4 right-4 z-[60] md:left-auto md:right-8 md:w-auto">
            <div className="rounded-md bg-black/70 text-white text-xs md:text-[12px] px-3 py-2 shadow-lg flex flex-col gap-1 max-w-md animate-in fade-in-0 slide-in-from-bottom-2">
              <div className="font-medium mb-0.5">모달 단축키</div>
              <div className="flex flex-wrap gap-x-3 gap-y-1">
                <span><span className="border border-white/30 rounded px-1 py-0.5 mr-1">←/→</span>이전/다음 글</span>
                <span><span className="border border-white/30 rounded px-1 py-0.5 mr-1">J/K</span>스크롤</span>
                <span><span className="border border-white/30 rounded px-1 py-0.5 mr-1">Space</span>페이지 스크롤</span>
                <span><span className="border border-white/30 rounded px-1 py-0.5 mr-1">Home/End</span>맨 위/아래</span>
              </div>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter } from 'next/navigation';
import MiniSearch, { type SearchResult } from 'minisearch';
import { Button } from '@/components/ui/button';
import { DialogTitle } from "@/components/ui/dialog";
import { CommandDialog, CommandInput, CommandList, CommandEmpty, CommandGroup, CommandItem } from '@/components/ui/command';
import { File } from 'lucide-react';

// Define the structure of the documents we stored in the index
interface SearchDocument {
  id: string;
  title: string;
  image?: string;
}

export function SearchBar() {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [results, setResults] = useState<(SearchResult & SearchDocument)[]>([]);
  const [loading, setLoading] = useState(false);

  // Use a ref to hold the minisearch instance
  const miniSearch = useRef<MiniSearch<SearchDocument> | null>(null);

  // Effect to handle keyboard shortcut for opening the search
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((open) => !open);
      }
    };
    document.addEventListener('keydown', down);
    return () => document.removeEventListener('keydown', down);
  }, []);

  // 2) 다이얼로그 열릴 때 로드
  useEffect(() => {
    if (open && !miniSearch.current) {
      setLoading(true);
      fetch('/data/search-index.json')
        .then(res => res.text())
        .then(data => {
          miniSearch.current = MiniSearch.loadJSON<SearchDocument>(data, {
            fields: ['title', 'content', 'keywords'],
            storeFields: ['id', 'title', 'image'],
            idField: 'id',
          });
        })
        .catch(err => console.error('Failed to load search index:', err))
        .finally(() => setLoading(false));
    }
  }, [open]);

  // 3) 검색 시 null 가드
  const handleSearch = useCallback((query: string) => {
    setSearch(query);
    const ms = miniSearch.current;
    if (query.length > 1 && ms) {
      // 결과에 storeFields가 이미 포함됨
      const searchResults = ms.search(query, { prefix: true, fuzzy: 0.2 }) as Array<SearchResult & SearchDocument>;
      setResults(searchResults);
    } else {
      setResults([]);
    }
  }, []);

  const handleSelect = (id: string) => {
    router.push(`/posts/${id}`);
    setOpen(false);
  };

  return (
    <>
      <Button
        variant="outline"
        className="relative h-8 w-full justify-start rounded-[0.5rem] bg-background text-sm font-normal text-muted-foreground shadow-none sm:pr-12"
        onClick={() => setOpen(true)}
      >
        <span className="hidden lg:inline-flex">게시물 검색...</span>
        <span className="inline-flex lg:hidden">검색...</span>
        <kbd className="pointer-events-none absolute right-[0.3rem] top-[0.3rem] hidden h-5 select-none items-center gap-1 rounded border bg-muted px-1.5 font-mono text-[10px] font-medium opacity-100 sm:flex">
          <span className="text-xs">⌘</span>K
        </kbd>
      </Button>

      <CommandDialog open={open} onOpenChange={setOpen}>
        <DialogTitle className="sr-only">검색하기</DialogTitle>

        <CommandInput
          placeholder="무엇이든 검색하세요..."
          value={search}
          onValueChange={handleSearch}
        />
        <CommandList>
          {loading && <CommandEmpty>인덱스를 불러오는 중...</CommandEmpty>}
          {!loading && results.length === 0 && search.length > 1 && <CommandEmpty>검색 결과가 없습니다.</CommandEmpty>}
          <CommandGroup heading="게시물">
            {results.map(({ id, title, image }) => (
              <CommandItem
                key={id}
                value={`${title}-${id}`}
                onSelect={() => handleSelect(id)}
                className="flex items-center"
              >
                {image ? (
                  <img src={image} alt={title} className="mr-2 h-8 w-8 object-cover rounded" />
                ) : (
                  <File className="mr-2 h-4 w-4" />
                )}
                <span>{title}</span>
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
      </CommandDialog>
    </>
  );
}

